def _emit_dialogue_memory(
    event_kind: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    *,
    state: Any = None,
    outcome: Any = None,
) -> dict[str, Any]:
    payload = _normalise_payload(event_kind, args, kwargs, state=state, outcome=outcome)

    try:
        from src.scripts.ZG_quests.sod_quest_dialogue_record_event import (
            sod_quest_dialogue_record_event as record_event,
        )
    except Exception:
        try:
            from src.scripts.ZG_quests.sod_quest_dialogue_record_event import (
                script_sod_quest_dialogue_record_event as record_event,
            )
        except Exception:
            record_event = None

    if record_event is not None:
        _call_best_effort(record_event, payload)

    return payload


def _has_stage_or_progress_changed(source: Any) -> bool:
    current_stage = _get_value(source, "stage_id", "stage", default=None)
    previous_stage = _get_value(source, "previous_stage_id", "old_stage_id", "from_stage_id", default=None)
    current_progress = _get_value(source, "progress", "stage_progress", default=None)
    previous_progress = _get_value(source, "previous_progress", "old_progress", "from_progress", default=None)

    stage_changed = previous_stage is not None and current_stage is not None and previous_stage != current_stage
    progress_changed = previous_progress is not None and current_progress is not None and previous_progress != current_progress
    return stage_changed or progress_changed


def sod_quest_runtime_update(*args: Any, **kwargs: Any) -> dict[str, Any]:
    source = _first_source(args, kwargs)
    event_kind = _build_constant("sod_quest_event_update", "sod_quest_event_update")
    if source is not None:
        _set_value(source, "event_kind", event_kind)
        _set_value(source, "event", event_kind)
        _set_default(source, "interaction_count", _get_value(source, "interaction_count", default=0) or 0)
        _set_value(source, "state", _get_value(source, "state", default="active") or "active")
        _set_value(source, "quest_state", _get_value(source, "quest_state", default="active") or "active")

    should_refresh = source is not None and _has_stage_or_progress_changed(source)
    force_refresh = bool(kwargs.get("force_refresh") or kwargs.get("refresh_memory"))
    if should_refresh or force_refresh:
        _set_value(source, "outcome", "updated")

    if should_refresh or force_refresh:
        payload = _emit_dialogue_memory(
            event_kind,
            args,
            kwargs,
            state=_get_value(source, "state", default="active") if source is not None else "active",
            outcome="updated" if should_refresh or force_refresh else _get_value(source, "outcome", default="updated"),
        )
    else:
        payload = _normalise_payload(
            event_kind,
            args,
            kwargs,
            state=_get_value(source, "state", default="active") if source is not None else "active",
            outcome=_get_value(source, "outcome", default="updated"),
        )
    return payload


def script_sod_quest_runtime_update(*args: Any, **kwargs: Any) -> dict[str, Any]:
    return sod_quest_runtime_update(*args, **kwargs)


SCRIPT = script_sod_quest_runtime_update

