# [ src/scripts/ZC_parties/decide_kingdom_party_ais.py:L2-L54 ] decide_kingdom_party_ais
("decide_kingdom_party_ais",
    [
      (try_for_range, ":faction_no", kingdoms_begin, kingdoms_end),
        (faction_slot_eq, ":faction_no", slot_faction_state, sfs_active),
        (neq, ":faction_no", "fac_player_supporters_faction"),
        (faction_get_slot, ":faction_ai_state", ":faction_no", slot_faction_ai_state),
        (neq, ":faction_ai_state", sfai_default),
        (faction_get_slot, ":faction_ai_object", ":faction_no", slot_faction_ai_object),
        (faction_get_slot, ":faction_marshall", ":faction_no", slot_faction_marshall),
        (gt, ":faction_marshall", 0),
        (neq, ":faction_marshall", "trp_player"),
        (troop_get_slot, ":faction_marshall_party", ":faction_marshall", slot_troop_leaded_party),
        (gt, ":faction_marshall_party", 0),
        (try_begin),
          (eq, ":faction_ai_state", sfai_gathering_army),
          (call_script, "script_party_set_ai_state", ":faction_marshall_party", spai_undefined, -1),
          (party_set_ai_initiative, ":faction_marshall_party", 100),
        (else_try),
          (eq, ":faction_ai_state", sfai_attacking_center),
          (call_script, "script_party_set_ai_state", ":faction_marshall_party", spai_besieging_center, ":faction_ai_object"),
          (party_set_ai_initiative, ":faction_marshall_party", 50),
        (else_try),
          (eq, ":faction_ai_state", sfai_raiding_village),
          (call_script, "script_party_set_ai_state", ":faction_marshall_party", spai_raiding_around_center, ":faction_ai_object"),
          (party_set_ai_initiative, ":faction_marshall_party", 50),
        (else_try),
          (eq, ":faction_ai_state", sfai_attacking_enemies_around_center),
          (call_script, "script_party_set_ai_state", ":faction_marshall_party", spai_patrolling_around_center, ":faction_ai_object"),
          (party_set_ai_initiative, ":faction_marshall_party", 50),
        (else_try),
          (eq, ":faction_ai_state", sfai_attacking_enemy_army),
          (call_script, "script_party_set_ai_state", ":faction_marshall_party", spai_engaging_army, ":faction_ai_object"),
          (party_set_ai_initiative, ":faction_marshall_party", 50),
        (try_end),
        (party_set_slot, ":faction_marshall_party", slot_party_commander_party, -1),
      (try_end),

      (try_for_range, ":troop_no", kingdom_heroes_begin, kingdom_heroes_end),
        (try_begin),
          (store_troop_faction, ":troop_faction", ":troop_no"),
          (neg|faction_slot_eq, ":troop_faction", slot_faction_marshall, ":troop_no"),
          (troop_get_slot, ":troop_party", ":troop_no", slot_troop_leaded_party),
          (gt, ":troop_party", 0),
          (party_is_active, ":troop_party"),
          (party_set_ai_initiative, ":troop_party", 100),
        (try_end),
        (call_script, "script_calculate_troop_ai", ":troop_no"),
      (try_end),

      (try_for_range, ":troop_no", kingdom_heroes_begin, kingdom_heroes_end),
        (call_script, "script_calculate_troop_ai_under_command", ":troop_no"),
      (try_end),
  ]),
# [ src/scripts/ZC_parties/determine_prisoner_agreed.py:L2-L60 ] determine_prisoner_agreed
("determine_prisoner_agreed",
                      [
                        (store_script_param, ":prisoner", 1),
                        (store_script_param, ":relation", 2),

                        # upper bound = Persuasion*3 + Charisma + Leadership*3 + Honor/2 - prisoner_level/3
                        (store_attribute_level, ":charisma", "trp_player", ca_charisma),
                        (store_skill_level, ":persuasion", "skl_persuasion", "trp_player"),
                        (store_skill_level, ":leadership", "skl_leadership", "trp_player"),
                        (val_mul, ":persuasion", 3),
                        (val_mul, ":leadership", 3),
                        (store_div, ":half_honor", "$player_honor", 2),
                        #(troop_get_slot, ":renown_factor", "trp_player", slot_troop_renown),
                        #(val_div, ":renown_factor", 100),
                        (store_character_level, ":prisoner_level", ":prisoner"),
                        (store_div, ":level_factor", ":prisoner_level", 3),
                        (assign,  ":upper_bound", ":persuasion"),
                        (val_add, ":upper_bound", ":leadership"),
                        (val_add, ":upper_bound", ":charisma"),
                        (val_add, ":upper_bound", ":half_honor"),
                        #(val_add, ":upper_bound", ":renown_factor"),
                        (val_sub, ":upper_bound", ":level_factor"),

                        #TODO: count how many individuals this prisoner represents in the player's priosoners party
                        #      and scale the % chance by that number (essentially, if 3 in stack, then 3x as likely one of them will agree)
                        (party_get_num_prisoner_stacks, ":num_stacks", "p_main_party"),
                        (try_for_range, ":index", 0, ":num_stacks"),
                          (party_prisoner_stack_get_troop_id, ":troop_no", "p_main_party", ":index"),
                          (eq, ":troop_no", ":prisoner"),
                          (party_prisoner_stack_get_size, ":count", "p_main_party", ":index"),
                          (val_mul, ":upper_bound", ":count"),
                        (try_end),

                        (val_min, ":relation", ":upper_bound"),

                        # determine their reaction (relation...upper_bound)
                        (store_random_in_range, ":reaction", ":relation", ":upper_bound"),

                        # record whether they agree or not
                        (try_begin),
                          (gt, ":reaction", 0),
                          (troop_set_slot, ":prisoner", slot_prisoner_agreed, 1),
                        (else_try),
                          (troop_set_slot, ":prisoner", slot_prisoner_agreed, 0),
                        (try_end),

                        # return the results
                        (troop_get_slot, reg0, ":prisoner", slot_prisoner_agreed),

                        # diagnostic only
                        (try_begin),
                          (eq, "$g_sod_debug", 1),
                          (assign, reg1, ":reaction"),
                          (assign, reg2, ":relation"),
                          (assign, reg3, ":upper_bound"),
                          (display_message, "@Prisoner agrees check: rolled a {reg1} out of a possible {reg2}..{reg3} = {reg0?agree:piss off}", debug_color),
                        (try_end),
                      ]
                    ),
