# [ src/scripts/ZC_parties/get_player_party_morale_values.py:L2-L62 ] get_player_party_morale_values
("get_player_party_morale_values",
    [
      (party_get_num_companion_stacks, ":num_stacks", "p_main_party"),
      (assign, ":num_men", 0),
      (try_for_range, ":i_stack", 1, ":num_stacks"),
        (party_stack_get_troop_id, ":stack_troop", "p_main_party", ":i_stack"),
        (try_begin),
          (troop_is_hero, ":stack_troop"),
          #MORDACHAI - reduce the negative morale of a hero
          (val_add, ":num_men", 1),
        (else_try),
          (party_stack_get_size, ":stack_size", "p_main_party", ":i_stack"),
          (val_add, ":num_men", ":stack_size"),
        (try_end),
      (try_end),

      #MORDACHAI - reduce the effect of party size on morale to 2/3
      (val_mul, ":num_men", 2),
      (val_div, ":num_men", 3),

      (assign, "$g_player_party_morale_modifier_party_size", ":num_men"),

      (store_skill_level, ":player_leadership", "skl_leadership", "trp_player"),
      #MORDACHAI - increase morale boost to leadership x 10 (was x 7)
      (store_mul, "$g_player_party_morale_modifier_leadership", ":player_leadership", 10),
      (assign, ":new_morale", "$g_player_party_morale_modifier_leadership"),
      (val_sub, ":new_morale", "$g_player_party_morale_modifier_party_size"),
      (val_add, ":new_morale", 50),

      (assign, "$g_player_party_morale_modifier_food", 0),
      (try_for_range, ":cur_edible", food_begin, food_end),
        (call_script, "script_cf_player_has_item_without_modifier", ":cur_edible", imod_rotten),
        (item_get_slot, ":food_bonus", ":cur_edible", slot_item_food_bonus),
        (val_add, "$g_player_party_morale_modifier_food", ":food_bonus"),
      (try_end),
      (val_add, ":new_morale", "$g_player_party_morale_modifier_food"),

      (try_begin),
        (eq, "$g_player_party_morale_modifier_food", 0),
        (assign, "$g_player_party_morale_modifier_no_food", 30),
        (val_sub, ":new_morale", "$g_player_party_morale_modifier_no_food"),
      (else_try),
        (assign, "$g_player_party_morale_modifier_no_food", 0),
      (try_end),

      (assign, "$g_player_party_morale_modifier_debt", 0),
      (try_begin),
        (val_max, "$g_player_debt_to_party_members", 0),
        (gt, "$g_player_debt_to_party_members", 0),
        (call_script, "script_calculate_player_faction_wage"),
        (assign, ":total_wages", reg0),
        (gt, ":total_wages", 0),
        (store_mul, "$g_player_party_morale_modifier_debt", "$g_player_debt_to_party_members", 10),
        (val_div, "$g_player_party_morale_modifier_debt", ":total_wages"),
        (val_clamp, "$g_player_party_morale_modifier_debt", 1, 31),
        (val_sub, ":new_morale", "$g_player_party_morale_modifier_debt"),
      (try_end),

      (val_clamp, ":new_morale", 0, 101),
      (assign, reg0, ":new_morale"),
  ]),
# [ src/scripts/ZC_parties/get_stack_with_rank.py:L2-L23 ] get_stack_with_rank
("get_stack_with_rank",
    [
      (store_script_param_1, ":party"), #Party_id
      (store_script_param_2, ":rank"), #Rank
      (party_get_num_companion_stacks, ":num_stacks", ":party"),
      (assign, reg(0), -1),
      (assign, ":num_total", 0),
      (try_for_range, ":i_stack", 0, ":num_stacks"),
        (eq, reg(0), -1), #continue only if we haven't found the result yet.
        (party_stack_get_troop_id,     ":stack_troop", ":party", ":i_stack"),
        (neg|troop_is_hero, ":stack_troop"),
        (party_stack_get_size,         ":stack_size", ":party", ":i_stack"),
        (party_stack_get_num_wounded,  ":num_wounded", ":party", ":i_stack"),
        (val_sub, ":stack_size", ":num_wounded"),
        (val_max, ":stack_size", 0),
        (val_add, ":num_total", ":stack_size"),
        (try_begin),
          (lt, ":rank", ":num_total"),
          (assign, reg(0), ":i_stack"),
        (try_end),
      (try_end),
  ]),
# [ src/scripts/ZC_parties/get_troop_attached_party.py:L2-L13 ] get_troop_attached_party
("get_troop_attached_party",
    [
      (store_script_param_1, ":troop_no"),

      (troop_get_slot, ":party_no", ":troop_no", slot_troop_leaded_party),
      (assign, ":attached_party_no", -1),
      (try_begin),
        (ge, ":party_no", 0),
        (party_get_attached_to, ":attached_party_no", ":party_no"),
      (try_end),
      (assign, reg0, ":attached_party_no"),
  ]),
# [ src/scripts/ZC_parties/hire_men_to_kingdom_hero_party.py:L2-L79 ] hire_men_to_kingdom_hero_party
("hire_men_to_kingdom_hero_party",
    [
      (store_script_param_1, ":troop_no"),

      (troop_get_slot, ":party_no", ":troop_no", slot_troop_leaded_party),
      (troop_get_slot, ":cur_wealth", ":troop_no", slot_troop_wealth),


      (assign, ":hiring_budget", ":cur_wealth"),
      (val_mul, ":hiring_budget", 3),
      (val_div, ":hiring_budget", 4),

      (assign, ":num_rounds", 1),

      (call_script, "script_party_get_ideal_size", ":party_no"),
      (assign, ":ideal_size", reg0),
      (store_mul, ":ideal_top_size", ":ideal_size", 3),
      (val_div, ":ideal_top_size", 2),

      (party_get_num_companions, ":party_size", ":party_no"),
      (try_for_range, ":unused", 0 , ":num_rounds"),
        (try_begin),
          (lt, ":party_size", ":ideal_size"),
          (gt, ":hiring_budget", reinforcement_cost),
          (gt, ":party_no", 0),
          (call_script, "script_cf_reinforce_party", ":party_no"),
          (val_sub, ":cur_wealth", reinforcement_cost),
          (troop_set_slot, ":troop_no", slot_troop_wealth, ":cur_wealth"),
		  (try_begin),
			(store_troop_faction, ":fac", ":troop_no"),
			(eq, ":fac", "fac_player_supporters_faction"),
			(eq, "$g_sod_debug", 1),
			(call_script, "script_store_troop_name", s5, ":troop_no"),
			(display_message, "@{s5} reinforced his party.", build_color),
		  (try_end),
        (else_try),
          (gt, ":party_size", ":ideal_top_size"),
          (store_troop_faction, ":troop_faction", ":troop_no"),
          (party_get_num_companion_stacks, ":num_stacks", ":party_no"),
          (assign, ":total_regulars", 0),
          (assign, ":total_regular_levels", 0),
          (try_for_range_backwards, ":i_stack", 0, ":num_stacks"),
            (party_stack_get_troop_id, ":stack_troop", ":party_no", ":i_stack"),
            (neg|troop_is_hero, ":stack_troop"),
            (party_stack_get_size, ":stack_size", ":party_no", ":i_stack"),
            (store_character_level, ":stack_level", ":stack_troop"),
            (store_troop_faction, ":stack_faction", ":stack_troop"),
            (try_begin),
              (eq, ":troop_faction", ":stack_faction"),
              (val_mul, ":stack_level", 3), #reducing the chance of the faction troops' removal
            (try_end),
            (val_mul, ":stack_level", ":stack_size"),
            (val_add, ":total_regulars", ":stack_size"),
            (val_add, ":total_regular_levels", ":stack_level"),
          (try_end),
          (gt, ":total_regulars", 0),
          (store_div, ":average_level", ":total_regular_levels", ":total_regulars"),
          (try_for_range_backwards, ":i_stack", 0, ":num_stacks"),
            (party_stack_get_troop_id, ":stack_troop", ":party_no", ":i_stack"),
            (neg|troop_is_hero, ":stack_troop"),
            (party_stack_get_size, ":stack_size", ":party_no", ":i_stack"),
            (store_character_level, ":stack_level", ":stack_troop"),
            (store_troop_faction, ":stack_faction", ":stack_troop"),
            (try_begin),
              (eq, ":troop_faction", ":stack_faction"),
              (val_mul, ":stack_level", 3),
            (try_end),
            (store_sub, ":level_dif", ":average_level", ":stack_level"),
            (val_div, ":level_dif", 3),
            (store_add, ":prune_chance", 10, ":level_dif"),
            (gt, ":prune_chance", 0),
            (call_script, "script_get_percentage_with_randomized_round", ":stack_size", ":prune_chance"),
            (gt, reg0, 0),
            (party_remove_members, ":party_no", ":stack_troop", reg0),
          (try_end),
        (try_end),
      (try_end),
  ]),
# [ src/scripts/ZC_parties/inflict_casualties_to_party.py:L2-L74 ] inflict_casualties_to_party
("inflict_casualties_to_party",
    [
      (party_clear, "p_temp_casualties"),
      (store_script_param_1, ":party"), #Party_id
      (call_script, "script_party_count_fit_regulars", ":party"),
      (assign, ":num_fit", reg(0)), #reg(47) = number of fit regulars.
      (store_script_param_2, ":num_attack_rounds"), #number of attacks
      (try_for_range, ":unused", 0, ":num_attack_rounds"),
        (gt, ":num_fit", 0),
        (store_random_in_range, ":attacked_troop_rank", 0 , ":num_fit"), #attack troop with rank reg(46)
        (assign, reg1, ":attacked_troop_rank"),
        (call_script, "script_get_stack_with_rank", ":party", ":attacked_troop_rank"),
        (assign, ":attacked_stack", reg(0)), #reg(53) = stack no to attack.
        (party_stack_get_troop_id,     ":attacked_troop", ":party", ":attacked_stack"),
        (store_character_level, ":troop_toughness", ":attacked_troop"),
		                    # twan new make elite better if bloodbath is used and mid level infantry a little tougher than cavalry and archers
		(troop_get_slot, ":trp_type", ":attacked_troop", kt_slot_troop_type),

        (try_begin),
			(eq, "$g_sod_autoresolve", 0),		
			(try_begin),                                     
				(le, ":troop_toughness", 10),
				(val_add, ":troop_toughness", 4),  #troop-toughness = level + 5
			(else_try),
				(this_or_next|le, ":troop_toughness", 20),
				(neq, ":trp_type", kt_troop_type_footsoldier),
				(val_add, ":troop_toughness", 5),
			(else_try),
				(lt, ":troop_toughness", 27),
				(val_add, ":troop_toughness", 6),
			(else_try),
				(store_sub, ":bonus", ":troop_toughness", 20),
				(val_min, ":bonus", 10), # don't increase level too much
				(val_add, ":troop_toughness", ":bonus"),
			(try_end),
        (else_try),
            (val_add, ":troop_toughness", 5),
        (try_end),
		(val_max, ":troop_toughness", 1),
		
		(try_begin),
		(eq, "$g_sod_autoresolve", 0),
		(store_div, ":wound_chance", ":troop_toughness", 12),	# twan new	
        (val_clamp, ":wound_chance", 1, 3),		# elites have 1/2 to be wounded, mid level 1/3, lowest levels (recruits) 1/5
		(else_try),
        (assign, ":wound_chance", 2),
        (try_end),  		
		   
        (assign, ":casualty_chance", 10000),
        (val_div, ":casualty_chance", ":troop_toughness"), #dying chance
        (try_begin),
          (store_random_in_range, ":rand_num", 0 , 10000),
          (lt, ":rand_num", ":casualty_chance"), #check chance to be a casualty
          (store_random_in_range, ":rand_num2", 0, 6), #check if this troop will be wounded or killed
          (try_begin),
            (troop_is_hero, ":attacked_troop"), #currently troop can't be a hero, but no harm in keeping this.
            (store_troop_health, ":troop_hp", ":attacked_troop"),
            (val_sub, ":troop_hp", 45),
            (val_max, ":troop_hp", 1),
            (troop_set_health, ":attacked_troop", ":troop_hp"),
          (else_try),
            (lt, ":rand_num2", ":wound_chance"), #wounded twan new
            (party_add_members, "p_temp_casualties", ":attacked_troop", 1),  # twan new end
            (party_wound_members, "p_temp_casualties", ":attacked_troop", 1),
            (party_wound_members, ":party", ":attacked_troop", 1),
          (else_try), #killed
            (party_add_members, "p_temp_casualties", ":attacked_troop", 1),
            (party_remove_members, ":party", ":attacked_troop", 1),
          (try_end),
          (val_sub, ":num_fit", 1), #adjust number of fit regulars.
        (try_end),
      (try_end),
  ]),
# [ src/scripts/ZC_parties/merc_party_change_state.py:L2-L154 ] merc_party_change_state
("merc_party_change_state",
  [
    (store_script_param_1, ":cur_party"),

    (party_get_slot, ":boss_troop", ":cur_party", slot_party_boss),
    (assign, ":old_boss_troop", ":boss_troop"),
    (party_get_slot, ":base", ":cur_party", slot_party_starting_base),
    (party_get_slot, ":guild_faction", ":cur_party", slot_party_orginal_faction),
    (assign, ":assigned", 0),

    # Ownership invariant:
    # - slot_party_boss always stores a troop id for AI-hired merc parties
    # - slot_party_commander_party stores the current leader/base party they follow
    # - slot_party_orginal_faction stores the guild/template source faction

    (try_begin),
      (is_between, ":boss_troop", kingdom_heroes_begin, kingdom_heroes_end),
      (neq, ":boss_troop", "trp_player"),
      (troop_get_slot, ":boss_party", ":boss_troop", slot_troop_leaded_party),
      (gt, ":boss_party", 0),
      (store_troop_faction, ":boss_faction", ":boss_troop"),
      (troop_get_slot, ":gold", ":boss_troop", slot_troop_wealth),
      (store_party_size, ":size", ":cur_party"),
      (val_mul, ":size", 5),
      (gt, ":gold", ":size"),
      (val_sub, ":gold", ":size"),
      (troop_set_slot, ":boss_troop", slot_troop_wealth, ":gold"),
      (store_current_day, ":cur_day"),
      (val_add, ":cur_day", 30),
      (party_set_slot, ":cur_party", slot_party_merc_contract, ":cur_day"),
      (party_set_slot, ":cur_party", slot_party_commander_party, ":boss_party"),
      (party_set_faction, ":cur_party", ":boss_faction"),
      (party_set_ai_object, ":cur_party", ":boss_party"),
      (party_set_ai_behavior, ":cur_party", ai_bhvr_escort_party),
      (assign, ":assigned", 1),
    (try_end),

    (try_begin),
      (eq, ":assigned", 0),
      (is_between, ":boss_troop", kingdom_heroes_begin, kingdom_heroes_end),
      (store_troop_faction, ":old_faction", ":boss_troop"),
      (try_for_range, ":new_boss", kingdom_heroes_begin, kingdom_heroes_end),
        (eq, ":assigned", 0),
        (store_troop_faction, ":new_boss_faction", ":new_boss"),
        (eq, ":old_faction", ":new_boss_faction"),
        (troop_get_slot, ":new_boss_party", ":new_boss", slot_troop_leaded_party),
        (gt, ":new_boss_party", 0),
        (try_begin),
          (faction_slot_eq, ":old_faction", slot_faction_leader, ":new_boss"),
          (assign, ":limit", 3),
        (else_try),
          (assign, ":limit", 1),
        (try_end),
        (assign, ":active_parties", 0),
        (try_for_parties, ":curr_party"),
          (party_slot_eq, ":curr_party", slot_party_type, spt_ai_mercenaries),
          (party_slot_eq, ":curr_party", slot_party_boss, ":new_boss"),
          (val_add, ":active_parties", 1),
        (try_end),
        (store_sub, ":free_slots", ":limit", ":active_parties"),
        (gt, ":free_slots", 0),
        (troop_get_slot, ":cur_banner", ":new_boss", slot_troop_banner_scene_prop),
        (try_begin),
          (gt, ":cur_banner", 0),
          (val_sub, ":cur_banner", banner_scene_props_begin),
          (val_add, ":cur_banner", banner_map_icons_begin),
          (party_set_banner_icon, ":cur_party", ":cur_banner"),
        (try_end),
        (store_current_day, ":cur_day"),
        (val_add, ":cur_day", 30),
        (party_set_faction, ":cur_party", ":new_boss_faction"),
        (party_set_slot, ":cur_party", slot_party_merc_contract, ":cur_day"),
        (try_begin),
          (is_between, ":old_boss_troop", kingdom_heroes_begin, kingdom_heroes_end),
          (troop_slot_eq, ":old_boss_troop", slot_troop_mercenaries, ":cur_party"),
          (troop_set_slot, ":old_boss_troop", slot_troop_mercenaries, -1),
        (try_end),
        (party_set_slot, ":cur_party", slot_party_boss, ":new_boss"),
        (party_set_slot, ":cur_party", slot_party_commander_party, ":new_boss_party"),
        (troop_set_slot, ":new_boss", slot_troop_mercenaries, ":cur_party"),
        (party_set_ai_object, ":cur_party", ":new_boss_party"),
        (party_set_ai_behavior, ":cur_party", ai_bhvr_escort_party),
        (assign, ":assigned", 1),
      (try_end),
    (try_end),

    (try_begin),
      (eq, ":assigned", 0),
      (gt, ":base", 0),
      (assign, ":active_parties", 0),
      (try_for_parties, ":curr_party"),
        (party_slot_eq, ":curr_party", slot_party_type, spt_ai_mercenaries),
        (party_slot_eq, ":curr_party", slot_party_starting_base, ":base"),
        (neq, ":curr_party", ":cur_party"),
        (party_get_slot, ":other_commander", ":curr_party", slot_party_commander_party),
        (eq, ":other_commander", ":base"),
        (val_add, ":active_parties", 1),
      (try_end),
      (store_sub, ":free_slots", 3, ":active_parties"),
      (gt, ":free_slots", 0),
      (party_set_slot, ":cur_party", slot_party_commander_party, ":base"),
      (party_set_ai_behavior, ":cur_party", ai_bhvr_patrol_party),
      (party_set_ai_object, ":cur_party", ":base"),
      (party_set_ai_patrol_radius, ":cur_party", 5),
      (store_current_day, ":cur_day"),
      (val_add, ":cur_day", 15),
      (party_set_slot, ":cur_party", slot_party_merc_contract, ":cur_day"),
      (party_set_faction, ":cur_party", "fac_commoners"),
      (party_set_banner_icon, ":cur_party", 0),
      (try_begin),
        (is_between, ":old_boss_troop", kingdom_heroes_begin, kingdom_heroes_end),
        (troop_slot_eq, ":old_boss_troop", slot_troop_mercenaries, ":cur_party"),
        (troop_set_slot, ":old_boss_troop", slot_troop_mercenaries, -1),
      (try_end),
      (party_set_slot, ":cur_party", slot_party_boss, -1),
      (try_begin),
        (eq, ":base", "p_sod_merc_guild_1"),
        (party_set_banner_icon, ":cur_party", "icon_banner_162"),
      (else_try),
        (eq, ":base", "p_sod_merc_guild_2"),
        (party_set_banner_icon, ":cur_party", "icon_banner_163"),
      (else_try),
        (eq, ":base", "p_sod_merc_guild_3"),
        (party_set_banner_icon, ":cur_party", "icon_banner_164"),
      (else_try),
        (eq, ":base", "p_sod_merc_guild_4"),
        (party_set_banner_icon, ":cur_party", "icon_banner_165"),
      (else_try),
        (eq, ":base", "p_sod_merc_guild_5"),
        (party_set_banner_icon, ":cur_party", "icon_banner_166"),
      (try_end),
      (assign, ":assigned", 1),
    (try_end),

    (try_begin),
      (eq, ":assigned", 0),
      (try_begin),
        (is_between, ":old_boss_troop", kingdom_heroes_begin, kingdom_heroes_end),
        (troop_slot_eq, ":old_boss_troop", slot_troop_mercenaries, ":cur_party"),
        (troop_set_slot, ":old_boss_troop", slot_troop_mercenaries, -1),
      (try_end),
      (party_set_slot, ":cur_party", slot_party_boss, -1),
      (party_set_slot, ":cur_party", slot_party_commander_party, -1),
      (party_set_faction, ":cur_party", "fac_commoners"),
      (party_set_banner_icon, ":cur_party", 0),
      (party_set_ai_behavior, ":cur_party", ai_bhvr_patrol_location),
      (try_begin),
        (gt, ":guild_faction", 0),
        (party_set_slot, ":cur_party", slot_party_orginal_faction, ":guild_faction"),
      (try_end),
    (try_end),
  ]
),
# [ src/scripts/ZC_parties/offer_ransom_amount_to_player_for_prisoners_in_party.py:L2-L26 ] offer_ransom_amount_to_player_for_prisoners_in_party
("offer_ransom_amount_to_player_for_prisoners_in_party",
        [(store_script_param, ":party_no", 1),
          (assign, ":result", 0),
          (party_get_num_prisoner_stacks, ":num_stacks", ":party_no"),
          (try_for_range, ":i_stack", 0, ":num_stacks"),
            (eq, ":result", 0),
            (party_prisoner_stack_get_troop_id, ":stack_troop", ":party_no", ":i_stack"),
            (troop_is_hero, ":stack_troop"),
            (this_or_next|troop_slot_eq, ":stack_troop", slot_troop_occupation, slto_kingdom_hero),
            (troop_slot_eq, ":stack_troop", slot_troop_occupation, slto_mercenary_lord),
            (store_troop_faction, ":stack_troop_faction", ":stack_troop"),
            (store_random_in_range, ":random_no", 0, 100),
            (try_begin),
              (faction_slot_eq, ":stack_troop_faction", slot_faction_state, sfs_active),
              (le, ":random_no", 5),
              (neq, "$g_ransom_offer_rejected", 1),
              (assign, ":num_stacks", 0), #break
              (assign, ":result", 1),
              (assign, "$g_ransom_offer_troop", ":stack_troop"),
              (assign, "$g_ransom_offer_party", ":party_no"),
              (jump_to_menu, "mnu_enemy_offer_ransom_for_prisoner"),
            (try_end),
          (try_end),
          (assign, reg0, ":result"),
      ]),
# [ src/scripts/ZC_parties/order_best_besieger_party_to_guard_center.py:L2-L60 ] order_best_besieger_party_to_guard_center
("order_best_besieger_party_to_guard_center",
    [
      (store_script_param, ":defeated_center", 1),
      (store_script_param, ":winner_faction", 2),
      (assign, ":best_party", -1),
      (assign, ":best_party_strength", 0),
	  
	  (str_store_party_name, s12, ":defeated_center"),
	  (str_store_faction_name, s13, ":winner_faction"),
     
    (try_for_range, ":kingdom_hero", kingdom_heroes_begin, kingdom_heroes_end), # tr0
        (troop_get_slot, ":kingdom_hero_party", ":kingdom_hero", slot_troop_leaded_party),
        (gt, ":kingdom_hero_party", 0),
        (party_is_active, ":kingdom_hero_party"), #twan it seems there were opcode invalid parties error coming from this script so I've added checks
        (store_distance_to_party_from_party, ":dist", ":kingdom_hero_party", ":defeated_center"),
        (lt, ":dist", 5),
        (store_faction_of_party, ":kingdom_hero_party_faction", ":kingdom_hero_party"),
        (eq, ":winner_faction", ":kingdom_hero_party_faction"),
	
    	(try_begin), #tr1
        (this_or_next|faction_slot_eq, ":winner_faction", slot_faction_marshall, ":kingdom_hero"),    #If marshall has captured the castle, then do not leave him behind.
        (eq, ":kingdom_hero", "trp_player"),
		(assign, ":has_besiege_ai", 0),
        (else_try),
        (assign, ":has_besiege_ai", 1),		# twan453 removed ai checks, any nearby party can be chosen
        (try_end), #tr1
      
      (try_begin), #tr2
        (eq, ":has_besiege_ai", 1),
			 (try_begin),  # tr3 Sod Twan
				(eq, "$g_sod_deactivate_ai", 0),
				(call_script, "script_party_calculate_siege_or_not_strength", ":kingdom_hero_party", 1),
				(assign, ":kingdom_hero_party_strength", reg0),
				     (try_begin),
					 (party_slot_eq, ":defeated_center", slot_town_lord, ":kingdom_hero"),
					 (val_mul, reg0, 3),
					 (try_end),
				(else_try),      
				(party_get_slot, ":kingdom_hero_party_strength", ":kingdom_hero_party", slot_party_cached_strength), #recently calculated
			 (try_end), # tr3 sod twan end
       

    	(gt, ":kingdom_hero_party_strength", ":best_party_strength"),
        (assign, ":best_party_strength", ":kingdom_hero_party_strength"),
        (assign, ":best_party", ":kingdom_hero_party"),
		(assign, ":best_hero", ":kingdom_hero"),

      (try_end), # end tr2   
      
      (try_end),#tr0 end the try for range
    
      (try_begin), #tr4
        (gt, ":best_party", 0),
        (call_script, "script_party_set_ai_state", ":best_party", spai_holding_center, ":defeated_center"),
		(troop_set_slot, ":best_hero", slot_lord_initiative, -10),  # should make hero guard center at least untill lords ai is recalculated
        (party_set_slot, ":best_party", slot_party_commander_party, -1),
        (party_set_flags, ":best_party", pf_default_behavior, 1),
	  (try_end), #tr4   #twan453new end
  ]),
# [ src/scripts/ZC_parties/party_add_party.py:L2-L8 ] party_add_party
("party_add_party",
    [
      (store_script_param_1, ":target_party"), #Target Party_id
      (store_script_param_2, ":source_party"), #Source Party_id
      (call_script, "script_party_add_party_companions",          ":target_party", ":source_party"),
      (call_script, "script_party_prisoners_add_party_prisoners", ":target_party", ":source_party"),
  ]),
# [ src/scripts/ZC_parties/party_add_party_companions.py:L2-L16 ] party_add_party_companions
("party_add_party_companions",
    [
      (store_script_param_1, ":target_party"), #Target Party_id
      (store_script_param_2, ":source_party"), #Source Party_id
      (party_get_num_companion_stacks, ":num_stacks", ":source_party"),
      (try_for_range, ":stack_no", 0, ":num_stacks"),
        (party_stack_get_troop_id,     ":stack_troop", ":source_party", ":stack_no"),
        (this_or_next|neg|troop_is_hero, ":stack_troop"),
        (eq, "$g_move_heroes", 1),
        (party_stack_get_size,         ":stack_size", ":source_party", ":stack_no"),
        (party_add_members, ":target_party", ":stack_troop", ":stack_size"),
        (party_stack_get_num_wounded, ":num_wounded", ":source_party", ":stack_no"),
        (party_wound_members, ":target_party", ":stack_troop", ":num_wounded"),
      (try_end),
  ]),
# [ src/scripts/ZC_parties/party_add_party_prisoners.py:L2-L14 ] party_add_party_prisoners
("party_add_party_prisoners",
    [
      (store_script_param_1, ":target_party"), #Target Party_id
      (store_script_param_2, ":source_party"), #Source Party_id
      (party_get_num_prisoner_stacks, ":num_stacks", ":source_party"),
      (try_for_range, ":stack_no", 0, ":num_stacks"),
        (party_prisoner_stack_get_troop_id,     ":stack_troop", ":source_party", ":stack_no"),
        (this_or_next|neg|troop_is_hero, ":stack_troop"),
        (eq, "$g_move_heroes", 1),
        (party_prisoner_stack_get_size,         ":stack_size", ":source_party", ":stack_no"),
        (party_add_members, ":target_party", ":stack_troop", ":stack_size"),
      (try_end),
  ]),
# [ src/scripts/ZC_parties/party_calculate_and_set_nearby_friend_strength.py:L2-L82 ] party_calculate_and_set_nearby_friend_strength
("party_calculate_and_set_nearby_friend_strength",
    [
      (store_script_param, ":party_no", 1),
      (assign, ":follower_strength", 0),
      (assign, ":friend_strength", 0),
      (assign, ":enemy_strength", 0),
      (store_faction_of_party, ":party_faction", ":party_no"),
	  (call_script, "script_get_number_of_factions_at_war_with_faction", ":party_faction"),  # twan new
	  (assign, ":num_enemy_factions", reg0),

      (store_add, ":end_cond", kingdom_heroes_end, 1),
      (try_for_range, ":iteration", kingdom_heroes_begin, ":end_cond"),
        (try_begin),
          (eq, ":iteration", kingdom_heroes_end),
          (assign, ":cur_troop", "trp_player"),
        (else_try),
          (assign, ":cur_troop", ":iteration"),
        (try_end),
        (troop_slot_eq, ":cur_troop", slot_troop_occupation, slto_kingdom_hero),
        (troop_get_slot, ":cur_troop_party", ":cur_troop", slot_troop_leaded_party),
        (ge, ":cur_troop_party", 0),
        (party_is_active, ":cur_troop_party"),
        (neq, ":party_no", ":cur_troop_party"),
        (party_get_slot, ":str", ":cur_troop_party", slot_party_cached_strength),
        (try_begin),
          (party_get_slot, ":commander_party", ":cur_troop_party", slot_party_commander_party),
          (eq, ":commander_party", ":party_no"),
          (val_add, ":follower_strength", ":str"),
        (try_end),
        (store_distance_to_party_from_party, ":distance", ":cur_troop_party", ":party_no"),
        (lt, ":distance", 10),
        (store_troop_faction, ":army_faction", ":cur_troop"),
        (store_relation, ":rel", ":army_faction", ":party_faction"),
        (try_begin),
          (eq, ":army_faction", ":party_faction"),
          (val_add, ":friend_strength", ":str"),   # SOD TWAN CHANGES BEGIN
		(else_try),
		  (gt, ":rel", 0),                  # friendly factions strength importance is proportionnal to number of common ennemies
          (call_script, "script_get_number_of_factions_at_war_with_faction_and_faction", ":party_faction", ":army_faction"),
          (val_mul, ":str", reg0),
          (val_div, ":str", ":num_enemy_factions"),		  
          (val_add, ":friend_strength", ":str"),
        (else_try),
          (lt, ":rel", 0),
          (val_add, ":enemy_strength", ":str"),
        (try_end),
      (try_end),
	  
	  (try_for_parties, ":party_b"),      # count mercenaries under contracts in nearby/enemy strengths 
	  (this_or_next|party_slot_eq, ":party_b", slot_party_type, spt_ai_mercenaries),
	  (party_slot_eq, ":party_b", slot_party_type, spt_player_mercenaries),
	  (store_distance_to_party_from_party, ":distance", ":cur_troop_party", ":party_b"),
      (lt, ":distance", 10),
      (store_faction_of_party, ":army_faction", ":party_b"),
	  (is_between, ":army_faction", kingdoms_begin, kingdoms_end),
      (store_relation, ":rel", ":army_faction", ":party_faction"),
        (try_begin),
          (eq, ":army_faction", ":party_faction"),
          (val_add, ":friend_strength", ":str"),  
		  (party_get_slot, ":boss", ":party_b", slot_party_boss),
          (try_begin),
          (is_between, ":boss", 1, "trp_black_army_leader_1"), 
          (troop_slot_eq, ":boss", slot_troop_leaded_party, ":party_no"),
          (val_add, ":follower_strength", ":str"),
		  (try_end),
		(else_try),
		  (gt, ":rel", 0),                  # friendly factions strength importance is proportionnal to number of common ennemies
          (call_script, "script_get_number_of_factions_at_war_with_faction_and_faction", ":party_faction", ":army_faction"),
          (val_mul, ":str", reg0),
          (val_div, ":str", ":num_enemy_factions"),		  
          (val_add, ":friend_strength", ":str"),
        (else_try),
          (lt, ":rel", 0),
          (val_add, ":enemy_strength", ":str"),
        (try_end),	                                  # twan new
	 (try_end),                                   # SOD TWAN CHANGES END
	 
      (party_set_slot, ":party_no", slot_party_follower_strength, ":follower_strength"),
      (party_set_slot, ":party_no", slot_party_nearby_friend_strength, ":friend_strength"),
      (party_set_slot, ":party_no", slot_party_nearby_enemy_strength, ":enemy_strength"),
  ]),
# [ src/scripts/ZC_parties/party_calculate_loot.py:L2-L95 ] party_calculate_loot
("party_calculate_loot",
    [
      (store_script_param_1, ":enemy_party"), #Enemy Party_id


      (call_script, "script_calculate_main_party_shares"),
      (assign, ":num_player_party_shares", reg0),
      #      (assign, ":num_ally_shares", reg1),
      #      (store_add, ":num_shares",  ":num_player_party_shares", ":num_ally_shares"),

      #Calculate player loot probability
      #      (assign, ":loot_probability", 100),
      #      (val_mul, ":loot_probability", 10),
      #      (val_div, ":loot_probability", ":num_shares"),

      (try_for_range, ":i_loot", 0, num_party_loot_slots),
        (store_add, ":cur_loot_slot", ":i_loot", slot_party_looted_item_1),
        (party_get_slot, ":item_no", "$g_enemy_party", ":cur_loot_slot"),
        (gt, ":item_no", 0),
        (party_set_slot, "$g_enemy_party", ":cur_loot_slot", 0),
        (val_sub, ":cur_loot_slot", slot_party_looted_item_1),
        (val_add, ":cur_loot_slot", slot_party_looted_item_1_modifier),
        (party_get_slot, ":item_modifier", "$g_enemy_party", ":cur_loot_slot"),
        (troop_add_item, "trp_temp_troop", ":item_no", ":item_modifier"),
      (try_end),
      (party_set_slot, "$g_enemy_party", slot_party_next_looted_item_slot, 0),

      (assign, ":num_looted_items", 0),
      (try_begin),
        (this_or_next|party_slot_eq, "$g_enemy_party", slot_party_type, spt_kingdom_caravan),
        (party_slot_eq, "$g_enemy_party", slot_party_type, spt_village_farmer),
        (store_mul, ":plunder_amount", player_loot_share, 30),
        (val_mul, ":plunder_amount", "$g_strength_contribution_of_player"),
        (val_div, ":plunder_amount", 100),
        (val_div, ":plunder_amount", ":num_player_party_shares"),
        (try_begin),
          (party_slot_eq, "$g_enemy_party", slot_party_type, spt_kingdom_caravan),
          #          (val_clamp, ":plunder_amount", 1, 50),
          (reset_item_probabilities, 100),
          (assign, ":range_min", trade_goods_begin),
          (assign, ":range_max", trade_goods_end),
        (else_try),
          (val_div, ":plunder_amount", 5),
          #          (val_clamp, ":plunder_amount", 1, 10),
          (reset_item_probabilities, 1),
          (assign, ":range_min", food_begin),
          (assign, ":range_max", food_end),
        (try_end),
        (store_sub, ":item_to_price_slot", slot_town_trade_good_prices_begin, trade_goods_begin),
        (try_for_range, ":cur_goods", ":range_min", ":range_max"),
          (store_add, ":cur_price_slot", ":cur_goods", ":item_to_price_slot"),
          (party_get_slot, ":cur_price", "$g_enemy_party", ":cur_price_slot"),
          (assign, ":cur_probability", 100),
          (val_mul, ":cur_probability", average_price_factor),
          (val_div, ":cur_probability", ":cur_price"),
          (val_mul, ":cur_probability", average_price_factor),
          (val_div, ":cur_probability", ":cur_price"),
          (val_mul, ":cur_probability", average_price_factor),
          (val_div, ":cur_probability", ":cur_price"),
          (assign, reg0, ":cur_probability"),
          (set_item_probability_in_merchandise, ":cur_goods", ":cur_probability"),
        (try_end),
        (troop_add_merchandise, "trp_temp_troop", itp_type_goods, ":plunder_amount"),
        (assign, reg5, ":plunder_amount"),
        (val_add, ":num_looted_items", ":plunder_amount"),
      (try_end),

      #Now loot the defeated party
      (store_mul, ":loot_probability", player_loot_share, 3),
      (val_mul, ":loot_probability", "$g_strength_contribution_of_player"),
      (party_get_skill_level, ":player_party_looting", "p_main_party", "skl_looting"),
      (val_add, ":player_party_looting", 10),
      (val_mul, ":loot_probability", ":player_party_looting"),
      (val_div, ":loot_probability", 10),
      (val_div, ":loot_probability", ":num_player_party_shares"),

      (party_get_num_companion_stacks, ":num_stacks", ":enemy_party"),
      (try_for_range, ":i_stack", 0, ":num_stacks"),
        (party_stack_get_troop_id,     ":stack_troop", ":enemy_party", ":i_stack"),
        (neg|troop_is_hero, ":stack_troop"),
        (party_stack_get_size, ":stack_size", ":enemy_party", ":i_stack"),
        (try_for_range, ":unused", 0, ":stack_size"),
          (troop_loot_troop, "trp_temp_troop", ":stack_troop", ":loot_probability"),
        (try_end),
      (try_end),
      (troop_get_inventory_capacity, ":inv_cap", "trp_temp_troop"),
      (try_for_range, ":i_slot", 0, ":inv_cap"),
        (troop_get_inventory_slot, ":item_id", "trp_temp_troop", ":i_slot"),
        (ge, ":item_id", 0),
        (val_add, ":num_looted_items", 1),
      (try_end),

      (assign, reg0, ":num_looted_items"),
  ]),
# [ src/scripts/ZC_parties/party_calculate_regular_strength.py:L2-L90 ] party_calculate_regular_strength
("party_calculate_regular_strength",
    [
      (store_script_param_1, ":party"), #Party_id
	  
	  (party_get_attached_to, ":attached_to", ":party"),  # SoD twan
	  
	  (try_begin),  
	  (this_or_next|is_between, ":party", walled_centers_begin, walled_centers_end),
      (this_or_next|is_between, ":attached_to", walled_centers_begin, walled_centers_end),
	  (party_slot_eq, ":party", slot_party_ai_state, spai_besieging_center),
	  (assign, ":siege", 1),
	  (else_try),
	  (assign, ":siege", 0),
	  (try_end),
      
      (assign, reg(0),0),
      (party_get_num_companion_stacks, ":num_stacks",":party"),
      (try_for_range, ":i_stack", 0, ":num_stacks"),
        (party_stack_get_troop_id, ":stack_troop",":party",":i_stack"),
        (neg|troop_is_hero, ":stack_troop"),
        (store_character_level, ":stack_strength", ":stack_troop"),
		
		(try_begin),            # SoD Twan change begin
		(ge, "$g_sod_autoresolve", 0),
		(troop_get_slot, ":trp_type", ":stack_troop", kt_slot_troop_type),
        (try_begin),
           (eq, ":siege", 1),
              (try_begin), 
              (eq, ":trp_type", kt_troop_type_cavalry),
			  (lt, ":stack_strength", 23),          # exclude the high level cavalry and heroes, who usually have good enough armors/skills to be usefull in sieges
              (val_div, ":stack_strength", 5),
              (val_mul, ":stack_strength", 3),
              (else_try),
              (eq, ":trp_type", kt_troop_type_archer),
 			  (val_mul, ":stack_strength", 4),
			  (val_div, ":stack_strength", 3),
			  (else_try),
			  (eq, ":trp_type", kt_troop_type_mtdarcher),
			  (val_mul, ":stack_strength", 6),
			  (val_div, ":stack_strength", 5),
			  (else_try),
			  (eq, ":trp_type", kt_troop_type_footsoldier),   #make elite infantry like huscarls as good as archers in sieges
		      (ge, ":stack_strength", 25),
              (val_mul, ":stack_strength", 4),
              (val_div, ":stack_strength", 3),
              (try_end),  			  
		      (try_begin),
			  (le, ":stack_strength", 12),             # low level units (as well as mid level cavalry) suck in sieges out of archers
			  (lt, ":trp_type", kt_troop_type_archer),
			  (val_div, ":stack_strength", 2),
			  (else_try),
			  (ge, ":stack_strength", 25),             # elites matter a lot in sieges last tier units bonus is increased
			  (val_mul, ":stack_strength", 4),
			  (val_div, ":stack_strength", 3),
			  (try_end),
		   (else_try),
		   (eq, ":siege", 0),
		       (try_begin),
			   (eq, ":trp_type", kt_troop_type_cavalry),
			   (val_mul, ":stack_strength", 3),
			   (val_div, ":stack_strength", 2),
			   (else_try),
		       (eq, ":trp_type", kt_troop_type_mtdarcher),
			   (val_mul, ":stack_strength", 4),
			   (val_div, ":stack_strength", 3),
			   (else_try),
			   (le, ":stack_strength", 15),           # low and mid level units are disadvantaged only if not mounted (and not as much as in sieges) 
			   (val_mul, ":stack_strength", 4),
			   (val_div, ":stack_strength", 5),
			   (try_end),
			   (try_begin),
			   (ge, ":stack_strength", 25),          # elite are advantaged but not as much as in sieges
			   (val_mul, ":stack_strength", 5),  
			   (val_div, ":stack_strength", 4),   # some examples : swadian knight lv25 cav (native : 14 / in siege : 20 / in open battle : 34) huscarl lv28 inf (native 16, siege 38 open 22)	
			   (try_end),                         # nord footman lv10 inf ( native 5, siege 3, open 4), 
			(try_end),                 
	    (try_end), # SoD Twan change end
		
        (val_add, ":stack_strength", 12),
        (val_mul, ":stack_strength", ":stack_strength"),
        (val_div, ":stack_strength", 100),
        (party_stack_get_size, ":stack_size",":party",":i_stack"),
        (party_stack_get_num_wounded, ":num_wounded",":party",":i_stack"),
        (val_sub, ":stack_size", ":num_wounded"),
        (val_max, ":stack_size", 0),
        (val_mul, ":stack_strength", ":stack_size"),
        (val_add,reg(0), ":stack_strength"),
      (try_end),
  ]),
