# [ src/scripts/ZD_centers/cf_village_recruit_volunteers_cond.py:L2-L40 ] cf_village_recruit_volunteers_cond
("cf_village_recruit_volunteers_cond",
        [(neg|party_slot_eq, "$current_town", slot_village_state, svs_looted),
          (neg|party_slot_eq, "$current_town", slot_village_state, svs_being_raided),
          (neg|party_slot_ge, "$current_town", slot_village_infested_by_bandits, 1),
          (store_faction_of_party, ":village_faction", "$current_town"),
          (party_get_slot, ":center_relation", "$current_town", slot_center_player_relation),
          (store_relation, ":village_faction_relation", ":village_faction", "fac_player_faction"),

          (ge, ":center_relation", 0),
          (this_or_next|ge, ":center_relation", 5),
          (this_or_next|eq, ":village_faction", "$players_kingdom"),
          (this_or_next|ge, ":village_faction_relation", 0),
          (this_or_next|eq, ":village_faction", "$supported_pretender_old_faction"),
          (             eq, "$players_kingdom", 0),

          #SOD Population Management Changes Begin
          # limit the number available accorrding to the amount of population above minimum for this village (they can't dig into the minimum required to be a village)
          (party_get_slot, ":volunteers", "$current_town", slot_center_volunteer_troop_amount),
          (party_get_slot, ":population", "$current_town", slot_center_sod_local_population),
          (val_sub, ":population", village_pop_min),
          (val_min, ":volunteers", ":population"),
          (party_set_slot, "$current_town", slot_center_volunteer_troop_amount, ":volunteers"),
          #SOD Population Management Changes End

          (try_begin),
            (eq, "$g_sod_debug", 1),
            (assign, reg0, ":center_relation"),
            (display_message, "@cf_village_recruit_volunteers_cond - village-player relation: {reg0}", debug_color),
            (party_get_slot, reg0, "$current_town", slot_center_volunteer_troop_type),
            (display_message, "@cf_village_recruit_volunteers_cond - troop type: {reg0}", debug_color),
            (party_get_slot, reg0, "$current_town", slot_center_volunteer_troop_amount),
            (display_message, "@cf_village_recruit_volunteers_cond - troop amount: {reg0}", debug_color),
          (try_end),

          (party_slot_ge, "$current_town", slot_center_volunteer_troop_amount, 1), #MORDACHAI- now we won't get the retarded "nobody seems to want to join you..."
          (party_slot_ge, "$current_town", slot_center_volunteer_troop_type, 1),
          (party_get_free_companions_capacity, ":free_capacity", "p_main_party"),
          (ge, ":free_capacity", 1),
      ]),
# [ src/scripts/ZD_centers/change_center_health.py:L2-L53 ] change_center_health
("change_center_health",
        [
          (store_script_param, ":center_no", 1),
          (store_script_param, ":difference", 2),
          (party_get_slot, ":health", ":center_no", slot_center_sod_local_health),
		  (assign, ":max", 101),
		  (try_begin),
			(this_or_next|party_slot_eq, ":center_no", slot_center_has_hospital, 1),
			(party_slot_eq, ":center_no", slot_center_has_ambulatory, 1),
			(val_add, ":max", 20),
		  (try_end),
		  (try_begin),
			(this_or_next|party_slot_eq, ":center_no", slot_center_has_canalization, 1),
			(party_slot_eq, ":center_no", slot_center_has_water_supply, 1),
			(val_add, ":max", 10),
		  (try_end),
			
          (val_clamp, ":health", -100, ":max"),
          (store_add, ":new_health", ":health", ":difference"),
          (val_clamp, ":new_health", -100, ":max"),
          (party_set_slot, ":center_no", slot_center_sod_local_health, ":new_health"),

          # notify the player depending on their desired messages
          (try_begin),
            # only display messages if the player wants them
            (eq, "$g_sod_hide_messages", 0),

            # only announce it for the player's fiefs (or his kingdom's fiefs)
            (store_faction_of_party, ":faction", ":center_no"),
            (this_or_next|party_slot_eq, ":center_no", slot_town_lord, "trp_player"),
            (eq, ":faction", "fac_player_supporters_faction"),

            # only say something if it changed brackets
            (call_script, "script_get_health_bracket", ":health"),
            (assign, ":old_bracket", reg0),
            (call_script, "script_get_health_bracket", ":new_health"),
            (assign, ":new_bracket", reg0),
            (neq, ":new_bracket", ":old_bracket"),

            # generate the message
            (call_script, "script_get_health_text", s1, ":health"),
            (call_script, "script_get_health_text", s2, ":new_health"),
            (str_store_party_name_link, s10, ":center_no"),
            (try_begin),
              (gt, ":new_health", ":health"),
              (display_message, "@{s10} population's health has grown from {s1} to {s2}.", green),
            (else_try),
              (display_message, "@{s10} population's health has declined from {s1} to {s2}.", red),
            (try_end),
          (try_end),
        ]
      ),
# [ src/scripts/ZD_centers/change_player_relation_with_center.py:L2-L34 ] change_player_relation_with_center
("change_player_relation_with_center",
    [
      (store_script_param_1, ":center_no"),
      (store_script_param_2, ":difference"),

      (party_get_slot, ":player_relation", ":center_no", slot_center_player_relation),
      (assign, reg1, ":player_relation"),
      (val_add, ":player_relation", ":difference"),
      (val_clamp, ":player_relation", -100, 101),
      (assign, reg2, ":player_relation"),
      (party_set_slot, ":center_no", slot_center_player_relation, ":player_relation"),

      (str_store_party_name_link, s1, ":center_no"),
      (store_sub, reg3, reg2, reg1),
      (try_begin),
        (gt, reg3, 0),
        (display_message, "@Your relation with {s1} has improved.", gain_relation_color),
      (else_try),
        (lt, reg3, 0),
        (display_message, "@Your relation with {s1} has deteriorated.", lose_relation_color),
      (try_end),
      (try_begin),
        (party_slot_eq, ":center_no", slot_party_type, spt_village),
        (call_script, "script_update_volunteer_troops_in_village", ":center_no"),
      (try_end),

      (try_begin),
        (this_or_next|is_between, "$g_talk_troop", village_elders_begin, village_elders_end),
        (is_between, "$g_talk_troop", mayors_begin, mayors_end),
        (assign, "$g_talk_troop_relation", ":player_relation"),
        (call_script, "script_setup_talk_info"),
      (try_end),
  ]),
