# [ src/scripts/ZD_centers/describe_center_relation.py:L2-L12 ] describe_center_relation
("describe_center_relation",
    [
      (store_script_param_1, ":sreg"),
      (store_script_param_2, ":relation"),
      (store_add, ":normalized_relation", ":relation", 100),
      (val_add, ":normalized_relation", 5),
      (store_div, ":str_offset", ":normalized_relation", 10),
      (val_clamp, ":str_offset", 0, 20),
      (store_add, ":str_id", "str_center_relation_mnus_100",  ":str_offset"),
      (str_store_string, ":sreg", ":str_id"),
  ]),
# [ src/scripts/ZD_centers/get_best_fief_name_of_troop.py:L2-L77 ] get_best_fief_name_of_troop
("get_best_fief_name_of_troop", [
	(store_script_param_1, ":string"),
	(store_script_param_2, ":troop_no"),
	
	(assign, ":continue", 0),

	(try_for_range, ":village_no", villages_begin, villages_end),
        (party_slot_eq, ":village_no", slot_town_lord, ":troop_no"),
        (str_store_party_name, s17, ":village_no"),
		(assign, ":continue", 1),
    (try_end),            
	(try_for_range, ":castle_no", castles_begin, castles_end),
	#	(val_add, ":castle", 1),
        (party_slot_eq, ":castle_no", slot_town_lord, ":troop_no"),
		(str_store_party_name, s17, ":castle_no"),
	#	(store_add, reg0, "str_castlename_0", ":castle"),
	#	(str_store_string, s17, reg0),
		(assign, ":continue", 1),
    (try_end), 
   (try_for_range, ":town_no", towns_begin, towns_end),  # should take a town name in priority
        (party_slot_eq, ":town_no", slot_town_lord, ":troop_no"),
        (str_store_party_name, s17, ":town_no"),
		(assign, ":continue", 1),
    (try_end),
	(try_begin),
		(store_troop_faction, ":faction", ":troop_no"),
		(faction_slot_eq, ":faction", slot_faction_leader, ":troop_no"),
		(try_begin),
			(eq, ":faction", "fac_kingdom_1"),
			(str_store_string, s17, "@Swadia"),
		(else_try),
			(eq, ":faction", "fac_kingdom_2"),
			(str_store_string, s17, "@Vaegirs"),
		(else_try),
			(eq, ":faction", "fac_kingdom_3"),
			(str_store_string, s17, "@Khergits"),
		(else_try),
			(eq, ":faction", "fac_kingdom_4"),
			(str_store_string, s17, "@the Nords"),
		(else_try),
			(eq, ":faction", "fac_kingdom_5"),
			(str_store_string, s17, "@Rhodok Republic"),
		(else_try),
			(eq, ":faction", "fac_kingdom_6"),
			(str_store_string, s17, "@the Imperial Legion"),
		(try_end),
		(assign, ":continue", 1),
	(try_end),
	(try_begin),
		(eq, ":troop_no", "trp_player"),
		(eq, "$g_sod_king", 1),
		(try_begin),
			(eq, "$g_sod_country", cb_antares),
			(str_store_string, s17, "@Antares"),
		(else_try),
			(eq, "$g_sod_country", cb_marina),
			(str_store_string, s17, "@Marina"),
		(else_try),
			(eq, "$g_sod_country", cb_aden),
			(str_store_string, s17, "@Aden"),
		(else_try),
			(eq, "$g_sod_country", cb_villian),
			(str_store_string, s17, "@Villian"),
		(else_try),
			(eq, "$g_sod_country", cb_zerrikan),
			(str_store_string, s17, "@Zerrikania"),
		(try_end),
		(assign, ":continue", 1),
	(try_end),
	(try_begin),
		(eq, ":continue", 1),
		(str_store_string, ":string", "@ of {s17}"),
	(else_try),
		(str_clear, ":string"),
	(try_end),
	]),
# [ src/scripts/ZD_centers/get_center_faction_relation_including_player.py:L2-L13 ] get_center_faction_relation_including_player
("get_center_faction_relation_including_player",
    [
      (store_script_param, ":center_no", 1),
      (store_script_param, ":target_faction_no", 2),
      (store_faction_of_party, ":center_faction", ":center_no"),
      (store_relation, ":reln", ":center_faction", ":target_faction_no"),
      (try_begin),
        (party_slot_eq, ":center_no", slot_town_lord, "trp_player"),
        (store_relation, ":reln", "fac_player_supporters_faction", ":target_faction_no"),
      (try_end),
      (assign, reg0, ":reln"),
  ]),
# [ src/scripts/ZD_centers/get_center_ideal_health.py:L6-L43 ] get_center_ideal_health
("get_center_ideal_health",
        [
          (store_script_param, ":center_no", 1),
          (call_script, "script_get_center_building_effect_totals", ":center_no"),
          (assign, ":building_health_bonus", reg6),
          (try_begin),
            (is_between, ":center_no", villages_begin, villages_end),
			(assign, ":ideal", 10),

            # land quality = -6..+9
            (party_get_slot, ":land_quality", ":center_no", slot_village_land_quality),
            (val_sub, ":ideal", 2), # -2..+3
            (val_mul, ":land_quality", 3), # 3 points per land quality
            (val_add, ":ideal", ":land_quality"),

            (val_add, ":ideal", ":building_health_bonus"),

            # population = -1 per 10 population outside of ideal
            (party_get_slot, ":population", ":center_no", slot_center_sod_local_population),
            (store_sub, ":crowding", village_pop_ideal, ":population"),
            (val_div, ":crowding", 10),
            (val_add, ":ideal", ":crowding"),

          (else_try),
            (assign, ":ideal", 10),

            (val_add, ":ideal", ":building_health_bonus"),

            # population = -1 per 30 population outside of ideal
            (party_get_slot, ":population", ":center_no", slot_center_sod_local_population),
            (store_sub, ":crowding", town_pop_ideal, ":population"),
            (val_div, ":crowding", 30),
            (val_add, ":ideal", ":crowding"),

          (try_end),
          (assign, reg0, ":ideal"),
        ]
      ),
# [ src/scripts/ZD_centers/get_center_relative_value.py:L2-L74 ] get_center_relative_value
("get_center_relative_value",
    [ (store_script_param_1, ":center_no"),
      (assign, ":player_center", 0), 
      (party_get_slot, ":population", ":center_no", slot_center_sod_local_population),
      (party_get_slot, ":health", ":center_no", slot_center_sod_local_health),
      (party_get_slot, ":prosperity", ":center_no", slot_town_prosperity),
      (store_faction_of_party, ":faction_no", ":center_no"),
		  (try_begin),
		  (eq, ":faction_no", "fac_player_supporters_faction"),
		  (assign, ":player_center", 1),
		  (party_get_slot, ":faith", ":center_no", slot_center_sod_local_faith),
		  (val_max, ":faith", 0),  # to avoid to advantage player, under average faith shouldn't reduce relative value (used by ai to chose the richest targets)
		  (val_add, ":faith", 100),
		  (val_div, ":faith", 2),
		  (try_end),
      (try_begin), 
      (party_slot_eq, ":center_no", slot_party_type, spt_town),
      (assign, ":max_pop", town_pop_max),
      (else_try),
      (assign, ":max_pop", village_pop_max),
      (try_end),
      (val_add, ":health", 100),
      (val_div, ":health", 2),
      (val_mul, ":population", 100),
      (val_div, ":population", ":max_pop"),
      (val_mul, ":prosperity", 3),
      (val_mul, ":population", 2),
      (store_add, reg0, ":prosperity", ":population"),
      (val_add, reg0, ":health"),
      (try_begin),
        (party_slot_eq, ":center_no", slot_party_type, spt_village),
        (party_slot_eq, ":center_no", slot_village_state, svs_being_raided),
        (val_sub, reg0, 20),
      (try_end),
      (try_begin),
        (party_slot_eq, ":center_no", slot_party_type, spt_village),
        (party_slot_eq, ":center_no", slot_village_state, svs_looted),
        (val_sub, reg0, 40),
      (try_end),
      (try_begin),
        (party_slot_eq, ":center_no", slot_party_type, spt_village),
        (party_slot_ge, ":center_no", slot_village_infested_by_bandits, 1),
        (val_sub, reg0, 15),
      (try_end),
      (try_begin),
        (this_or_next|party_slot_eq, ":center_no", slot_party_type, spt_town),
        (party_slot_eq, ":center_no", slot_party_type, spt_castle),
        (assign, ":bound_village_pressure", 0),
        (try_for_range, ":village_no", villages_begin, villages_end),
          (party_slot_eq, ":village_no", slot_village_bound_center, ":center_no"),
          (try_begin),
            (party_slot_eq, ":village_no", slot_village_state, svs_being_raided),
            (val_add, ":bound_village_pressure", 20),
          (else_try),
            (party_slot_eq, ":village_no", slot_village_state, svs_looted),
            (val_add, ":bound_village_pressure", 35),
          (try_end),
          (try_begin),
            (party_slot_ge, ":village_no", slot_village_infested_by_bandits, 1),
            (val_add, ":bound_village_pressure", 10),
          (try_end),
        (try_end),
        (val_sub, reg0, ":bound_village_pressure"),
      (try_end),
      (val_max, reg0, 0),
		  (try_begin),
		  (eq, ":player_center", 1),
		  (val_add, reg0, ":faith"),
		  (val_div, reg0, 7),
		  (else_try),
		  (val_div, reg0, 6),
		  (try_end),
      ]),
# [ src/scripts/ZD_centers/get_center_threat_level.py:L2-L82 ] get_center_threat_level
("get_center_threat_level",
   [ (store_script_param_1, ":center_no"),
     (assign, ":threat_level", 0),
     (try_begin),
		 (neg|is_between, ":center_no", centers_begin, centers_end),
		 (display_log_message, "@Bug : center get threat level was called for something else than a center."),
	(else_try),
		 (this_or_next|party_slot_eq, ":center_no", slot_party_type, spt_castle),
		 (party_slot_eq, ":center_no", slot_party_type, spt_town),
		 (party_get_slot, ":besiegers", ":center_no", slot_center_is_besieged_by),
		 (party_get_slot, ":enemy_str", ":center_no", slot_party_nearby_enemy_strength),
		 (party_get_slot, ":garrison_str", ":center_no", slot_party_cached_strength),
		 (party_get_slot, ":friendly_str", ":center_no", slot_party_nearby_friend_strength),
		 (party_get_num_companions, ":num_comp", ":center_no"),
		 (val_mul, ":enemy_str", 4),
		 (val_max, ":garrison_str", 250),
		 (val_mul, ":garrison_str", 2),
			  (try_begin),
			   (eq, ":besiegers", -1), 
			   (lt, ":enemy_str", "$g_average_lord_army_strength"), # no threat level if enemies are less than 1/4 of average strength and center isn't besieged
			   (gt, ":num_comp", 60),
			   (assign, ":threat_level", 0),
			  (else_try),
			    (eq, ":besiegers", -1),
                (lt, ":enemy_str", ":garrison_str"), # no threat level one if garrison alone is two time stronger than enemies and center isn't besieged
                (gt, ":num_comp", 60),
				(assign, ":threat_level", 0), 				
			  (else_try),
			   (ge, ":besiegers", 0),
			   (party_is_active, ":besiegers"), 
			   (party_get_slot, ":besieger_party_str", ":besiegers", slot_party_cached_strength),
			   (val_add, ":enemy_str", ":besieger_party_str"),  # besieger party count 2 time
			   (val_div, ":friendly_str", 2),  # troops out of the castle matter less 
				  (try_begin),
				  (party_slot_eq, ":center_no", slot_center_siege_with_belfry, 1),
				  (val_mul, ":garrison_str", 3),
				  (else_try),
				  (val_mul, ":garrison_str", 2),
				  (try_end),
			   (val_add, ":friendly_str", ":garrison_str"),
			   (store_div, ":threat_level", ":enemy_str", ":friendly_str"),
			   (val_max, ":threat_level", 2),    #twan new
			   (val_add, ":threat_level", 1),
			  (else_try),
			   (val_add, ":friendly_str", ":garrison_str"),
			   (store_div, ":threat_level", ":enemy_str", ":friendly_str"),
			   (lt, ":num_comp", 50),
			   (val_max, ":threat_level", 2), #twan454
			  (try_end),
			  
		(else_try), # villages
			(try_begin),
		   (this_or_next|party_slot_eq, ":center_no", slot_village_state, svs_looted),
		   (party_slot_eq, ":center_no", slot_village_state, svs_deserted),
		   (assign, ":threat_level", 0),  # already too late
			(else_try),
		   (party_slot_eq, ":center_no", slot_village_state, svs_being_raided),
		   (assign, ":threat_level", 10),
			(else_try),
		   (assign, ":village_militia_threat", 0),
		   (party_get_slot, ":village_militia", ":center_no", slot_center_npc_volunteer_troop_amount),
		   (val_max, ":village_militia", 0),
		   (store_div, ":village_militia_threat", ":village_militia", 4),
		   (assign, ":threat_level", ":village_militia_threat"),
		   (party_get_slot, ":last_enemy", ":center_no", slot_center_last_spotted_enemy),
				(try_begin),
				(ge, ":last_enemy", 0),
				(party_is_active, ":last_enemy"),
				(party_get_slot, ":enemy_str", ":last_enemy", slot_party_cached_strength),
				(party_get_slot, ":enemies_str", ":last_enemy", slot_party_nearby_friend_strength),
				(val_div, ":enemies_str", 2),
				(val_add, ":enemy_str", ":enemies_str"),
				(store_div, ":threat_level", ":enemy_str", 2500),
				(val_clamp, ":threat_level", 1, 6),
				(val_add, ":threat_level", ":village_militia_threat"),
				 (try_end),
			(try_end),
     (try_end),
     (val_min, ":threat_level", 10),
     (assign, reg0, ":threat_level"),
     ]),
