# [ src/scripts/ZF_factions/lord_set_his_personnal_objective.py:L2-L33 ] lord_set_his_personnal_objective
("lord_set_his_personnal_objective",
  [ (store_script_param_1, ":lord_no"),
    (store_script_param_2, ":number_of_centers"),
    (store_mul, ":ignore_center", ":number_of_centers", 10),
    (val_add, ":ignore_center", 30),	# a lord will only chose an objective if there is a castle under this dist of all his other centers
    (store_troop_faction, ":lord_fac", ":lord_no"), 
    (assign, ":compare", 1000),
    (assign, ":objective", -1),
	
    (try_for_range, ":castle", castles_begin, castles_end),
    (store_faction_of_party, ":castle_fac", ":castle"),
    (store_relation, ":rln", ":lord_fac", ":castle_fac"),
    (lt, ":rln", 0),
    (assign, ":score", 0),
        (try_for_range, ":lord_center", centers_begin, centers_end),
        (party_slot_eq, ":lord_center", slot_town_lord, ":lord_no"),
        (store_distance_to_party_from_party, ":dist", ":lord_center", ":castle"),
            (try_begin),
            (lt, ":dist", ":ignore_center"),   
            (val_add, ":score", ":dist"),
            (else_try),
            (assign, ":score", 1001),
            (try_end),
        (try_end),
        (try_begin),
        (lt, ":score", ":compare"),
        (assign, ":objective", ":castle"),
        (assign, ":compare", ":score"),
        (try_end),
    (try_end),
    (troop_set_slot, ":lord_no", slot_lord_personnal_objective, ":objective"),
    ]),
