	(ge, "$g_presentation_obj_9", 0),
	(ge, "$g_presentation_obj_10", 0),
	(ge, "$g_presentation_obj_11", 0),
	(ge, "$g_presentation_obj_12", 0),
	(ge, "$g_presentation_obj_13", 0),
