# [ src/scripts/ZZ_common_array_processing/activate_law.py:L2-L7 ] activate_law
("activate_law",
  [
    (store_script_param_1, ":law"),
    (call_script, "script_sod_law_migrate_player_legacy_slots"),
    (call_script, "script_sod_law_add_to_faction", "fac_player_supporters_faction", ":law"),
  ]),
# [ src/scripts/ZZ_common_array_processing/agent_reassign_team.py:L2-L29 ] agent_reassign_team
("agent_reassign_team",
      [
        (store_script_param, ":agent_no", 1),
        (get_player_agent_no, ":player_agent"),
        (try_begin),
          (ge, ":player_agent", 0),
          (agent_is_human, ":agent_no"),
          (agent_is_ally, ":agent_no"),
          (agent_get_party_id, ":party_no", ":agent_no"),
          (neq, ":party_no", "p_main_party"),
          (assign, ":continue", 1),
          (store_faction_of_party, ":party_faction", ":party_no"),
          (try_begin),
            (eq, ":party_faction", "$players_kingdom"),
            (is_between, "$players_kingdom", kingdoms_begin, kingdoms_end),
            (faction_slot_eq, "$players_kingdom", slot_faction_marshall, "trp_player"),
            (assign, ":continue", 0),
          (else_try),
            (party_stack_get_troop_id, ":leader_troop_id", ":party_no", 0),
            (neg|is_between, ":leader_troop_id", kingdom_heroes_begin, kingdom_heroes_end),
            (assign, ":continue", 0),
          (try_end),
          (eq, ":continue", 1),
          (agent_get_team, ":player_team", ":player_agent"),
          (val_add, ":player_team", 2),
          (agent_set_team, ":agent_no", ":player_team"),
        (try_end),
    ]),
# [ src/scripts/ZZ_common_array_processing/auto_loot_all.py:L2-L175 ] auto_loot_all
("auto_loot_all",
                      [
                        (assign, ":debug", 1),

                        # get count of stacks in player's party
                        (party_get_num_companion_stacks, ":num_stacks", "p_main_party"),

                        # record what items the npc used to have equipped in each slot
                        (try_for_range, ":i_stack", 0, ":num_stacks"),
                          (party_stack_get_troop_id, ":troop", "p_main_party", ":i_stack"),
                          (troop_slot_eq, ":troop", slot_troop_occupation, slto_player_companion),

                          #DEBUG
                          (try_begin),
                            (eq, ":debug", 2),
                            (call_script, "script_store_troop_name_link", s60, ":troop"),
                            (str_store_string, s1, "@{s60}'s equipment"),
                            (assign, ":debug_count", 0),
                          (try_end),

                          (try_for_range, ":i_equipment", ek_item_0, ek_food),

                            # store the original item
                            (troop_get_inventory_slot, ":item", ":troop", ":i_equipment"),
                            (store_add, ":i_troop_slot", ":i_equipment", slot_troop_item_0 - ek_item_0),
                            (troop_set_slot, ":troop", ":i_troop_slot", ":item"),

                            # store the original imod
                            (troop_get_inventory_slot_modifier, ":imod", ":troop", ":i_equipment"),
                            (store_add, ":i_troop_slot", ":i_equipment", slot_troop_item_0_imod - ek_item_0),
                            (troop_set_slot, ":troop", ":i_troop_slot", ":imod"),

                            #DEBUG
                            (try_begin),
                              (eq, ":debug", 2),
                              (try_begin),
                                (ge, ":item", 0),
                                (call_script, "script_describe_item_with_imod", s2, ":item", ":imod"),
                                (try_begin),
                                  (eq, ":debug_count", 0),
                                  (str_store_string, s1, "@{s1}: {s2}"),
                                (else_try),
                                  (str_store_string, s1, "@{s1}, {s2}"),
                                (try_end),
                                (val_add, ":debug_count", 1),
                              (try_end),
                            (try_end),

                            # make a determination of whether this npc should restrict themselves to mounted compatible equipment
                            (eq, ":i_equipment", ek_horse),
                            (try_begin),
                              # check if we're upgrading horses, or simply have one currently
                              (troop_get_slot, ":upg_horses", ":troop", slot_troop_upgrade_horse),
                              (this_or_next|eq, ":upg_horses", 1),
                              (ge, ":item", 0),
                              # only upgrade to items that can be used on horseback
                              (troop_set_slot, ":troop", slot_troop_restrict_mounted, 1),
                            (else_try),
                              # allow dismounted-only weapons & shield
                              (troop_set_slot, ":troop", slot_troop_restrict_mounted, 0),
                            (try_end),

                          (try_end), #(try_for_range, ":i_equipment", ek_item_0, ek_food),

                          #DEBUG
                          (try_begin),
                            (eq, ":debug", 2),
                            (gt, ":debug_count", 0),
                            (display_message, s1),
                          (try_end),

                        (try_end), #(try_for_range, ":i_stack", 0, ":num_stacks"),

                        # initial search for the best item available
                        (try_for_range, ":i_stack", 0, ":num_stacks"),
                          (party_stack_get_troop_id, ":troop", "p_main_party", ":i_stack"),
                          (troop_slot_eq, ":troop", slot_troop_occupation, slto_player_companion),
                          (troop_get_slot, ":require_mount_compatible", ":troop", slot_troop_restrict_mounted),
                          (call_script, "script_auto_loot_troop", ":troop", "$pool_troop", ":require_mount_compatible"),
                        (try_end),

                        # once more to pick up any discards
                        (try_for_range, ":i_stack", 0, ":num_stacks"),
                          (party_stack_get_troop_id, ":troop", "p_main_party", ":i_stack"),
                          (troop_slot_eq, ":troop", slot_troop_occupation, slto_player_companion),
                          (troop_get_slot, ":require_mount_compatible", ":troop", slot_troop_restrict_mounted),
                          (call_script, "script_auto_loot_troop", ":troop", "$pool_troop", ":require_mount_compatible"),
                        (try_end),

                        # a final time with relaxed settings to allow them to try to use horseback incompatible items IFF they didn't end up with a horse
                        (try_for_range, ":i_stack", 0, ":num_stacks"),
                          (party_stack_get_troop_id, ":troop", "p_main_party", ":i_stack"),
                          (troop_slot_eq, ":troop", slot_troop_occupation, slto_player_companion),

                          # only do this final step for those who were previously restricting themselves, and didn't find a horse
                          (troop_slot_eq, ":troop", slot_troop_restrict_mounted, 1),
                          (troop_slot_eq, ":troop", ek_horse, -1),
                          (call_script, "script_auto_loot_troop", ":troop", "$pool_troop", 0),
                        (try_end),

                        # accumulate the composite message of every change to every companion in s30
                        (str_clear, s30),
                        (assign, ":total", 0),
                        (try_for_range, ":i_stack", 0, ":num_stacks"),
                          (party_stack_get_troop_id, ":troop", "p_main_party", ":i_stack"),
                          (troop_slot_eq, ":troop", slot_troop_occupation, slto_player_companion),

                          # accumulate the text of all items this companion has newly equipped
                          (str_clear, s1),
                          (assign, ":changed", 0),
                          (try_for_range, ":i_equipment", ek_item_0, ek_food),
                            # retrieve the items
                            (store_add, ":i_troop_slot", ":i_equipment", slot_troop_item_0 - ek_item_0),
                            (troop_get_slot, ":old_item", ":troop", ":i_troop_slot"),
                            (troop_get_inventory_slot, ":new_item", ":troop", ":i_equipment"),

                            # retrieve the imods
                            (store_add, ":i_troop_slot", ":i_equipment", slot_troop_item_0_imod - ek_item_0),
                            (troop_get_slot, ":old_imod", ":troop", ":i_troop_slot"),
                            (troop_get_inventory_slot_modifier, ":new_imod", ":troop", ":i_equipment"),

                            # update our strings & count if this is not the same item as before
                            (ge, ":new_item", 0), # only report actual items, not the lack of an item
                            (this_or_next|neq, ":new_item", ":old_item"),
                            (             neq, ":new_imod", ":old_imod"),
                            (call_script, "script_describe_item_with_imod", s2, ":new_item", ":new_imod"),

                            (try_begin),
                              (ge, ":changed", 2),
                              (str_store_string, s1, "@{s2}, {s1}"),
                            (else_try),
                              (eq, ":changed", 1),
                              (str_store_string, s1, "@{s2}, and {s1}."),
                            (else_try),
                              (str_store_string, s1, "@{s2}"),
                            (try_end),
                            (val_add, ":changed", 1),

                            #DEBUG
                            (try_begin),
                              (eq, ":debug", 1),

                              (call_script, "script_describe_item_with_imod", s10, ":new_item", ":new_imod"),
                              (call_script, "script_get_item_score_with_imod", ":new_item", ":new_imod"),
                              (str_store_string, s10, "@{s10}({reg0})"),

                              (call_script, "script_describe_item_with_imod", s11, ":old_item", ":old_imod"),
                              (call_script, "script_get_item_score_with_imod", ":old_item", ":old_imod"),
                              (str_store_string, s11, "@{s11}({reg0})"),

                              (call_script, "script_store_troop_name_link", s12, ":troop"),
                              (display_message, "@{s12} replaced {s11} with {s10}", debug_color),
                            (try_end),
                          (try_end),

                          # append a message for this companion, if they equipped at least one new thing
                          (try_begin),
                            (gt, ":changed", 0),
                            (call_script, "script_store_troop_name_link", s2, ":troop"),
                            (str_store_string, s30, "@{s30}^{s2} equipped {s1}"),
                            (val_add, ":total", ":changed"),
                          (try_end),
                        (try_end),

                        # inform the player if nothing was exchanged
                        (try_begin),
                          (eq, ":total", 0),
                          (str_store_string, s30, "@^^^Unfortunately, there wasn't anything left worth equiping."),
                        (try_end),

                        # Done. Now sort the remainder
                        (troop_sort_inventory, "$pool_troop"),
                      ]
                    ),
# [ src/scripts/ZZ_common_array_processing/coherence.py:L2-L67 ] coherence
("coherence",
                      [
                        (get_scene_boundaries, pos3, pos4),
                        (assign, ":num_allies", 0),
                        (assign, ":coh_allies", 0),
                        (assign, ":num_enemies", 0),
                        (assign, ":coh_enemies", 0),
                        (try_for_agents, ":agent"),
                          (agent_is_ally, ":agent"),
                          (agent_is_human, ":agent"),
                          (store_agent_hit_points, ":hitpoints", ":agent", 0),
                          (agent_get_troop_id, ":troop_type", ":agent"),
                          (store_character_level, ":troop_level", ":troop_type"),
                          #(val_div, ":troop_level", 10),
                          (val_mul, ":hitpoints", ":troop_level"),
						  #SoD begin
                          (val_add, ":num_allies", 1),
						  #SoD end
                          (val_add, ":coh_allies", ":hitpoints"),
                        (else_try),
                          (agent_is_human, ":agent"),
                          (store_agent_hit_points, ":hitpoints", ":agent", 0),
                          (agent_get_troop_id, ":troop_type", ":agent"),
                          (store_character_level, ":troop_level", ":troop_type"),
                          #(val_div, ":troop_level", 10),
                          (val_mul, ":hitpoints", ":troop_level"),
						  #SoD begin
                          (val_add, ":num_enemies", 1),
						  #SoD end
                          (val_add, ":coh_enemies", ":hitpoints"),
                        (end_try),
                        (val_div, ":coh_allies", ":num_allies"),
                        (assign, "$allies_coh_base", ":coh_allies"),
						#SoD begin battle advantage also takes troop level into account now, it will have influence on morale, each point of BA is 5% more or less morale
						(assign, ":advantage", "$sod_battle_advantage"),
						(try_begin),
							(gt, "$sod_battle_advantage", 0),
							(val_mul, ":advantage", 5),
							(val_add, ":advantage", 100),
							(val_mul, "$allies_coh_base", ":advantage"),
							(val_div, "$allies_coh_base", 100),
						(try_end),
						#SoD  player's party morale will influence his battle morale, no such thing is done for computer,
						#AI is retarded already and let's asume that enemy is always happy,
						#finally some reason to keep really high morale! Better grab more food!
						  (party_get_morale, ":map_morale", "p_main_party"),
						  (val_div, ":map_morale", 2),
						  (val_add, ":map_morale", 100),
						  (val_mul, "$allies_coh_base", ":map_morale"),
						  (val_div, "$allies_coh_base", 150),	
                        (assign, "$allies_coh", "$allies_coh_base"),
						(assign, ":kills", "$new_kills"),
						(val_mul, ":kills", 10),
                        (val_add, "$allies_coh", ":kills"),
                        (val_div, ":coh_enemies", ":num_enemies"),
						(try_begin),
							(lt, "$sod_battle_advantage", 0),
							(val_mul, ":advantage", -5),
							(val_add, ":advantage", 100),
							(val_mul, ":coh_enemies", ":advantage"),
							(val_div, ":coh_enemies", 100),
						(try_end),
                        (assign, "$enemies_coh", ":coh_enemies"),
						#SoD end
                      ]
                    ),
# [ src/scripts/ZZ_common_array_processing/consume_food.py:L2-L19 ] consume_food
("consume_food",
      [(store_script_param, ":selected_food", 1),
        (troop_get_inventory_capacity, ":capacity", "trp_player"),
        (try_for_range, ":cur_slot", 0, ":capacity"),
          (troop_get_inventory_slot, ":cur_item", "trp_player", ":cur_slot"),
          (is_between, ":cur_item", food_begin, food_end),
          (troop_get_inventory_slot_modifier, ":item_modifier", "trp_player", ":cur_slot"),
          (neq, ":item_modifier", imod_rotten),
          (item_slot_eq, ":cur_item", slot_item_is_checked, 0),
          (item_set_slot, ":cur_item", slot_item_is_checked, 1),
          (val_sub, ":selected_food", 1),
          (lt, ":selected_food", 0),
          (assign, ":capacity", 0),
          (troop_inventory_slot_get_item_amount, ":cur_amount", "trp_player", ":cur_slot"),
          (val_sub, ":cur_amount", 1),
          (troop_inventory_slot_set_item_amount, "trp_player", ":cur_slot", ":cur_amount"),
        (try_end),
    ]),
# [ src/scripts/ZZ_common_array_processing/convert_3d_pos_to_map_pos.py:L2-L16 ] convert_3d_pos_to_map_pos
("convert_3d_pos_to_map_pos",
      [(set_fixed_point_multiplier, 1000),
        (position_transform_position_to_local, pos3, pos2, pos1),
        (position_get_x, ":agent_x_pos", pos3),
        (position_get_y, ":agent_y_pos", pos3),
        (val_div, ":agent_x_pos", "$g_battle_map_scale"),
        (val_div, ":agent_y_pos", "$g_battle_map_scale"),
        (set_fixed_point_multiplier, 1000),
        (store_sub, ":map_x", 980, "$g_battle_map_width"),
        (store_sub, ":map_y", 730, "$g_battle_map_height"),
        (val_add, ":agent_x_pos", ":map_x"),
        (val_add, ":agent_y_pos", ":map_y"),
        (position_set_x, pos0, ":agent_x_pos"),
        (position_set_y, pos0, ":agent_y_pos"),
    ]),
# [ src/scripts/ZZ_common_array_processing/deactivate_law.py:L2-L7 ] deactivate_law
("deactivate_law",
  [
    (store_script_param_1, ":law"),
    (call_script, "script_sod_law_migrate_player_legacy_slots"),
    (call_script, "script_sod_law_remove_from_faction", "fac_player_supporters_faction", ":law"),
  ]),
# [ src/scripts/ZZ_common_array_processing/determine_and_start_forced_rest.py:L2-L75 ] determine_and_start_forced_rest
("determine_and_start_forced_rest",
	  [	 
	  (assign, ":remaining_time", "$post_battle_forced_rest_time"),
	  
	  (assign, "$post_battle_forced_rest_time", 0),
	  
	  (store_div, ":defeated_enemy_strength", "$g_starting_strength_enemy_party", 3),
      (val_add, "$post_battle_forced_rest_time", ":defeated_enemy_strength"),
	  
	  (call_script, "script_party_count_fit_for_battle", "p_main_party"),
	  (assign, ":unwounded", reg0),
	  (party_get_num_companions, ":num_comp", "p_main_party"),
	  (party_get_num_prisoners, ":num_pris", "p_main_party"),
      (store_add, ":total_size", ":num_comp", ":num_pris"),
	  
	  (try_begin),
	  (ge, ":total_size", 120),
	  (store_div, ":big_party", ":total_size", 60),
	  (val_mul, "$post_battle_forced_rest_time", ":big_party"),  # double base duration for every 60 guys above 60
      (try_end),
	  
	  (try_begin),
		  (lt, ":num_comp", 20),
		  (eq, ":unwounded", ":total_size"),
		  (lt, ":remaining_time", 10),
		  (assign, "$post_battle_forced_rest_time", 0),
		  (assign, "$g_start_postbattle_forced_rest", 0),  # no forced rest if the character is quasi alone, has no wounded/prisoner and his party wasn't tired
	  
	  (else_try),
	  
		  (store_sub, ":small_party", 60, ":num_comp"),    # reduce duration if less than 60 companions
		  (val_min, ":small_party", 0),
		  (val_add, ":unwounded", ":small_party"),
		  (val_mul, ":unwounded", 100),
		  (val_div, ":unwounded", ":total_size"),   # prisoners slow the party and count as woundeds
		  (val_div, "$post_battle_forced_rest_time", ":unwounded"),
		  
		  (party_get_morale, ":morale", "p_main_party"),
		  (val_max, ":morale", 25),                 # low morale can triple duration no more
		  (val_mul, "$post_battle_forced_rest_time", 75),
		  (val_div, "$post_battle_forced_rest_time", ":morale"),
		  (val_max, "$post_battle_forced_rest_time", 12), # minimum added fatigue		  
		  
		  (val_add, "$post_battle_forced_rest_time", ":remaining_time"),
		  (val_min, "$post_battle_forced_rest_time", 60), # no more than 6 hours total
		  
		  (store_mul, ":chance_to_rest", "$post_battle_forced_rest_time", 2),   # instead of an unoticeable short rest after each battle
		  (val_sub, ":chance_to_rest", 10),                                     # make the party take an occasionnal long rest after several
		  (store_random_in_range, ":rnd", 0, 100),                              
		  
	  (try_begin),  
	  (eq, "$g_sod_debug", 1),
	  #(assign, ":rnd", 0),  #debug test forced rest
	  (assign, reg1, "$post_battle_forced_rest_time"),
	  (assign, reg2, ":defeated_enemy_strength"),
	  (assign, reg3, ":morale"),
	  (display_log_message, "@Forced rest system is working, forced rest time {reg1}, defeated army strength {reg2}, morale {reg3}.", debug_color),
      (try_end),
		  
	(try_begin),
    (lt, ":rnd", ":chance_to_rest"), 	
    (gt, "$post_battle_forced_rest_time", 12),  # twan456 no forced rest for minimum small battles exhaustion 	
	(assign, "$g_start_postbattle_forced_rest", 1),	
    (assign, "$g_is_in_forced_rest", 1),	
		 (try_begin),
		 (le, "$post_battle_forced_rest_time", 30),
         (rest_for_hours, 3, 1, 1), # rest will be interrupted by trigger 132
		 (else_try),
		 (rest_for_hours, 7, 2, 1), # rest at twice speed if resting for more than 3 hours
		 (try_end),	
    (try_end),
	  
	  (try_end),	  
	  ]),
# [ src/scripts/ZZ_common_array_processing/enter_court.py:L2-L89 ] enter_court
("enter_court",
    [
      (store_script_param_1, ":center_no"),

      (assign, "$talk_context", tc_court_talk),

      (set_jump_mission, "mt_visit_town_castle"),
      (party_get_slot, ":castle_scene", ":center_no", slot_town_castle),
      (modify_visitors_at_site, ":castle_scene"),
      (reset_visitors),
      #Adding guards
      (store_faction_of_party, ":center_faction", ":center_no"),
      (faction_get_slot, ":guard_troop", ":center_faction", slot_faction_guard_troop),
      (try_begin),
        (le, ":guard_troop", 0),
        (assign, ":guard_troop", "trp_swadian_sergeant"),
      (try_end),
      (set_visitor, 6, ":guard_troop"),
      (set_visitor, 7, ":guard_troop"),
	  
      #SoD COURT BEGIN
      (try_begin),
        (this_or_next|eq, ":center_faction", "fac_player_faction"),
        (eq, ":center_faction", "fac_player_supporters_faction"),
        (set_visitor, 17, "trp_sod_marshal"),
        (set_visitor, 18, "trp_sod_chancellor"),
        (set_visitor, 19, "trp_sod_treasurer"),
        (troop_set_slot, "trp_sod_marshal", slot_troop_sod_court, ":center_no"), #SoD ARMY MANAGEMENT
		(try_begin),
			(eq, "$g_sod_sa_in_court", 1),
			(set_visitor, 20, "trp_sod_strategy_advisor"),
		(try_end),
      (try_end),
	  (try_begin),
        (neq, ":center_faction", "fac_player_supporters_faction"),
		(faction_get_slot, ":leader", ":center_faction", slot_faction_leader),
		(party_slot_eq, ":center_no", slot_town_lord, ":leader"),
		(faction_get_slot,":m_guild", ":center_faction", slot_faction_merc_pact),
		(gt, ":m_guild", 0),
		(faction_get_slot,":representative", ":m_guild", slot_guild_representative),
		(set_visitor, 17, ":representative"),
	  (try_end),
      #SoD COURT END
	  #Sod now jester is available even before player creates a kingdom
	  (set_visitor, 16, "trp_sod_jester"),
      #SoD following was changed from (assign, ":cur_pos", 16),
	  
      (try_begin),
        (eq, ":center_faction", "fac_player_supporters_faction"),
		(assign, ":cur_pos", 21),
		(try_for_range, ":guild", guilds_begin, guilds_end),
			(store_relation, ":rel", "fac_player_faction", ":guild"),
			(ge, ":rel", 30),
			(faction_get_slot,":representative", ":guild", slot_guild_representative),
			(set_visitor, ":cur_pos", ":representative"),
			(val_add, ":cur_pos", 1),
		(try_end),
		(try_begin),
			(store_relation, ":rel", "fac_player_faction", "fac_commoners"),
			(ge, ":rel", 30),
			(set_visitor, ":cur_pos", ransom_brokers_begin),
			(val_add, ":cur_pos", 1),
		(try_end),
	  (else_try),
		(assign, ":cur_pos", 18),
	  (try_end),
	  
      (call_script, "script_get_heroes_attached_to_center", ":center_no", "p_temp_party"),
      (party_get_num_companion_stacks, ":num_stacks", "p_temp_party"),
      (try_for_range, ":i_stack", 0, ":num_stacks"),
        (party_stack_get_troop_id, ":stack_troop", "p_temp_party", ":i_stack"),
        (lt, ":cur_pos", 32), # spawn up to entry point 32
        (set_visitor, ":cur_pos", ":stack_troop"),
        (val_add, ":cur_pos", 1),
      (try_end),
      (try_for_range, ":cur_troop", heroes_begin, heroes_end),
        (troop_slot_eq, ":cur_troop", slot_troop_occupation, slto_kingdom_lady),
        (troop_slot_eq, ":cur_troop", slot_troop_cur_center, ":center_no"),
        (lt, ":cur_pos", 32), # spawn up to entry point 32
        (set_visitor, ":cur_pos", ":cur_troop"),
        (val_add, ":cur_pos", 1),
      (try_end),


      (jump_to_scene, ":castle_scene"),
      (scene_set_slot, ":castle_scene", slot_scene_visited, 1),
      (change_screen_mission),
  ]),
# [ src/scripts/ZZ_common_array_processing/enter_dungeon.py:L2-L25 ] enter_dungeon
("enter_dungeon",
    [
      (store_script_param_1, ":center_no"),
      (store_script_param_2, ":mission_template_no"),

      (set_jump_mission, ":mission_template_no"),
      (party_get_slot, ":dungeon_scene", ":center_no", slot_town_prison),

      (modify_visitors_at_site, ":dungeon_scene"), (reset_visitors),
      (assign, ":cur_pos", 16),
      (call_script, "script_get_heroes_attached_to_center_as_prisoner", ":center_no", "p_temp_party"),
      (party_get_num_companion_stacks, ":num_stacks", "p_temp_party"),
      (try_for_range, ":i_stack", 0, ":num_stacks"),
        (party_stack_get_troop_id, ":stack_troop", "p_temp_party", ":i_stack"),
        (lt, ":cur_pos", 32), # spawn up to entry point 32
        (set_visitor, ":cur_pos", ":stack_troop"),
        (val_add, ":cur_pos", 1),
      (try_end),

      (set_jump_entry, 0),
      (jump_to_scene, ":dungeon_scene"),
      (scene_set_slot, ":dungeon_scene", slot_scene_visited, 1),
      (change_screen_mission),
  ]),
