# [ src/scripts/ZZ_common_array_processing/fix_sod_has_a.py:L2-L32 ] fix_sod_has_a
("fix_sod_has_a",
                      [
                        (store_script_param, ":center", 1),
                        (store_script_param, ":building_start", 2),
                        (store_script_param, ":offset", 3),

                        # adjust to be zero based
                        (val_sub, ":offset", 1),

                        # one past end
                        (store_add, ":building_end", ":building_start", 5),

                        # fix existing building of this type
                        (assign, ":has_a", 0),
                        (try_for_range, ":building", ":building_start", ":building_end"),
                          (party_slot_ge, ":center", ":building", 1),
                          (assign, ":has_a", 1),
                          (party_set_slot, ":center", ":building", 0),
                        (try_end),
                        (store_add, ":building", ":building_start", ":offset"),
                        (party_set_slot, ":center", ":building", ":has_a"),

                        # fix under construction building of this type
                        (party_get_slot, ":building", ":center", slot_center_current_improvement),
                        (try_begin),
                          (is_between, ":building", ":building_start", ":building_end"),
                          (store_add, ":building", ":building_start", ":offset"),
                          (party_set_slot, ":center", slot_center_current_improvement, ":building"),
                        (try_end),
                      ]
                    ),
# [ src/scripts/ZZ_common_array_processing/flee_allies.py:L2-L76 ] flee_allies
("flee_allies",
                      [
                        (get_scene_boundaries, pos3, pos4),

                        (position_get_x, ":xmin", pos3),
                        (position_get_y, ":ymin", pos3),
                        (position_get_x, ":xmax", pos4),
                        (position_get_y, ":ymax", pos4),

                        (val_div, ":xmin", 100),
                        (val_div, ":xmax", 100),

                        (store_random_in_range, ":xrout_point3", ":xmin", ":xmax"),
                        (val_mul, ":xrout_point3", 100),
                        (store_random_in_range, ":yrout_point3", ":xmin", ":xmax"),
                        (val_mul, ":yrout_point3", 100),
                        (store_random_in_range, ":xrout_point4", ":xmin", ":xmax"),
                        (val_mul, ":xrout_point4", 100),
                        (store_random_in_range, ":yrout_point4", ":xmin", ":xmax"),
                        (val_mul, ":yrout_point4", 100),

                        (val_mul, ":xmin", 100),
                        (val_mul, ":xmax", 100),

                        (val_add, ":xrout_point3", ":xmin"),
                        (val_add, ":xrout_point3", ":xmin"),
                        (val_add, ":xrout_point3", ":xmin"),
                        (val_div, ":xrout_point3", 4),
                        (position_set_x, pos3, ":xrout_point3"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_div, ":yrout_point3", 4),
                        (position_set_y, pos3, ":yrout_point3"),

                        (val_add, ":xrout_point4", ":xmax"),
                        (val_add, ":xrout_point4", ":xmax"),
                        (val_add, ":xrout_point4", ":xmax"),
                        (val_div, ":xrout_point4", 4),
                        (position_set_x, pos4, ":xrout_point4"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_div, ":yrout_point4", 4),
                        (position_set_y, pos4, ":yrout_point4"),

                        (store_skill_level, ":leader", "skl_leadership", "trp_player"),
                        (try_for_agents, ":agent"),
                          (agent_is_alive, ":agent"),
                          (agent_is_human, ":agent"),
                          (agent_is_ally, ":agent"),
                          (store_agent_hit_points, ":hitpoints", ":agent", 0),
                          (agent_get_troop_id, ":troop_type", ":agent"),
                          (store_character_level, ":troop_level", ":troop_type"),
						  #SoD begin troop level should matter more! Peasants should run while Knights still stand
						  (val_div, ":hitpoints", 3), #So that 100% hp unit also has a chance to run
                          (val_mul, ":troop_level", 3),
                          (val_add, ":hitpoints", ":troop_level"),
						  #sod end
                          (assign, ":chance_ply", 100),
                          (val_sub, ":chance_ply", ":hitpoints"),
                          (val_sub, ":chance_ply", ":leader"),
                          (val_div, ":chance_ply", 2),
                          (store_random_in_range, ":routed", 1, 101),
                          (try_begin),
                            (le, ":routed", ":chance_ply"),
                            #(display_message, "@One ally runs!", debug_color),
                            (agent_get_position, pos2, ":agent"),
                            (position_move_z, pos2, 200, 0),
                            (agent_clear_scripted_mode, ":agent"),
                            (agent_set_scripted_destination, ":agent", pos4, 1),
                          (try_end),
                        (end_try),
                      ]
                    ),
