# [ src/scripts/ZZ_common_array_processing/rout_allies.py:L2-L76 ] rout_allies
("rout_allies",
                      [
                        (get_scene_boundaries, pos3, pos4),

                        (position_get_x, ":xmin", pos3),
                        (position_get_y, ":ymin", pos3),
                        (position_get_x, ":xmax", pos4),
                        (position_get_y, ":ymax", pos4),

                        (val_div, ":xmin", 100),
                        (val_div, ":xmax", 100),

                        (store_random_in_range, ":xrout_point3", ":xmin", ":xmax"),
                        (val_mul, ":xrout_point3", 100),
                        (store_random_in_range, ":yrout_point3", ":xmin", ":xmax"),
                        (val_mul, ":yrout_point3", 100),
                        (store_random_in_range, ":xrout_point4", ":xmin", ":xmax"),
                        (val_mul, ":xrout_point4", 100),
                        (store_random_in_range, ":yrout_point4", ":xmin", ":xmax"),
                        (val_mul, ":yrout_point4", 100),

                        (val_mul, ":xmin", 100),
                        (val_mul, ":xmax", 100),

                        (val_add, ":xrout_point3", ":xmin"),
                        (val_add, ":xrout_point3", ":xmin"),
                        (val_add, ":xrout_point3", ":xmin"),
                        (val_div, ":xrout_point3", 4),
                        (position_set_x, pos3, ":xrout_point3"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_div, ":yrout_point3", 4),
                        (position_set_y, pos3, ":yrout_point3"),

                        (val_add, ":xrout_point4", ":xmax"),
                        (val_add, ":xrout_point4", ":xmax"),
                        (val_add, ":xrout_point4", ":xmax"),
                        (val_div, ":xrout_point4", 4),
                        (position_set_x, pos4, ":xrout_point4"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_div, ":yrout_point4", 4),
                        (position_set_y, pos4, ":yrout_point4"),

                        (store_skill_level, ":leader", "skl_leadership", "trp_player"),
                        (try_for_agents, ":agent"),
                          (agent_is_alive, ":agent"),
                          (agent_is_human, ":agent"),
                          (agent_is_ally, ":agent"),
                          (store_agent_hit_points, ":hitpoints", ":agent", 0),
                          (agent_get_troop_id, ":troop_type", ":agent"),
                          (store_character_level, ":troop_level", ":troop_type"),
						  #Sod begin begin troop level should matter more! Peasants should run while Knights still stand
                          (val_div, ":hitpoints", 5), #So that 100% hp unit also has a chance to run
                          (val_mul, ":troop_level", 3),
                          (val_add, ":hitpoints", ":troop_level"),
						  #Sod end
                          (assign, ":chance_ply", 100),
                          (val_sub, ":chance_ply", ":hitpoints"),
                          (val_sub, ":chance_ply", ":leader"),
                          #SOD (val_sub, ":chance_ply", ":troop_level"),
                          (store_random_in_range, ":routed", 1, 101),
                          (try_begin),
                            (le, ":routed", ":chance_ply"),
                            #(display_message, "@One ally runs!", debug_color),
                            (agent_get_position, pos2, ":agent"),
                            (position_move_z, pos2, 200, 0),
                            (agent_clear_scripted_mode, ":agent"),
                            (agent_set_scripted_destination, ":agent", pos4, 1),
                          (try_end),
                        (end_try),
                      ]
                    ),
# [ src/scripts/ZZ_common_array_processing/rout_check.py:L2-L45 ] rout_check
("rout_check",
                      [
						  
						(assign, ":ally", "$allies_coh"),
                        #(assign, reg2, "$allies_coh"),
                      #  (display_message, "@allies {reg2}% cohesion!", debug_color),
                        (assign, ":enemy", "$enemies_coh"),
                      #  (assign, reg2, "$enemies_coh"),
                       # (display_message, "@enemies {reg2}% cohesion!", debug_color),
                      # (val_sub, ":ally", ":enemy"),
                      # (assign, reg2, ":ally"),
                       # (display_message, "@difference {reg2}.", debug_color),
						
						(try_begin),
							(gt, "$allies_coh", "$enemies_coh"),
							(val_div, ":ally", ":enemy"),
							(gt, ":ally", 5),
							(display_message, "@Your army has crushing advantage!", 0x7ccd7c),
							(call_script, "script_rout_enemies"),
							(assign, "$airout", 1),
						(else_try),
							(gt, "$enemies_coh", "$allies_coh"),
							(val_div, ":enemy", ":ally"),
							(gt, ":enemy", 5),
							(display_message, "@Your enemy has crushing advantage!", red),
							(call_script, "script_rout_allies"),
							(assign, "$rout", 1),
						(try_end),
						
                        #(try_begin),
                      #    (ge, ":ally", 400),
                      #    (display_message, "@Your enemies flee in terror!", 0x7ccd7c),
                     #     (call_script, "script_rout_enemies"),
                     #     (assign, "$airout", 1),
                     #   (try_end),

                     #   (try_begin),
                     #     (le, ":ally", -400),
                      #    (display_message, "@Your troops flee in terror!", red),
                     #    (call_script, "script_rout_allies"),
                     #     (assign, "$rout", 1),
                     #   (try_end),
                      ]
                    ),
# [ src/scripts/ZZ_common_array_processing/rout_enemies.py:L2-L73 ] rout_enemies
("rout_enemies",
                      [
                        (get_scene_boundaries, pos3, pos4),

                        (position_get_x, ":xmin", pos3),
                        (position_get_y, ":ymin", pos3),
                        (position_get_x, ":xmax", pos4),
                        (position_get_y, ":ymax", pos4),

                        (val_div, ":xmin", 100),
                        (val_div, ":xmax", 100),

                        (store_random_in_range, ":xrout_point3", ":xmin", ":xmax"),
                        (val_mul, ":xrout_point3", 100),
                        (store_random_in_range, ":yrout_point3", ":xmin", ":xmax"),
                        (val_mul, ":yrout_point3", 100),
                        (store_random_in_range, ":xrout_point4", ":xmin", ":xmax"),
                        (val_mul, ":xrout_point4", 100),
                        (store_random_in_range, ":yrout_point4", ":xmin", ":xmax"),
                        (val_mul, ":yrout_point4", 100),

                        (val_mul, ":xmin", 100),
                        (val_mul, ":xmax", 100),

                        (val_add, ":xrout_point3", ":xmin"),
                        (val_add, ":xrout_point3", ":xmin"),
                        (val_add, ":xrout_point3", ":xmin"),
                        (val_div, ":xrout_point3", 4),
                        (position_set_x, pos3, ":xrout_point3"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_add, ":yrout_point3", ":ymin"),
                        (val_div, ":yrout_point3", 4),
                        (position_set_y, pos3, ":yrout_point3"),

                        (val_add, ":xrout_point4", ":xmax"),
                        (val_add, ":xrout_point4", ":xmax"),
                        (val_add, ":xrout_point4", ":xmax"),
                        (val_div, ":xrout_point4", 4),
                        (position_set_x, pos4, ":xrout_point4"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_add, ":yrout_point4", ":ymax"),
                        (val_div, ":yrout_point4", 4),
                        (position_set_y, pos4, ":yrout_point4"),

                        (try_for_agents, ":agent"),
                          (agent_is_alive, ":agent"),
                          (agent_is_human, ":agent"),
                          (neg|agent_is_ally, ":agent"),
                          (store_agent_hit_points, ":hitpoints", ":agent", 0),
                          (agent_get_troop_id, ":troop_type", ":agent"),
                          (store_character_level, ":troop_level", ":troop_type"),
                          #Sod begin begin troop level should matter more! Peasants should run while Knights still stand
                          (val_div, ":hitpoints", 5), #So that 100% hp unit also has a chance to run
                          (val_mul, ":troop_level", 3),
                          (val_add, ":hitpoints", ":troop_level"),
						  #Sod end
                          (assign, ":chance_ply", 100),
                          (val_sub, ":chance_ply", ":hitpoints"),
                          (val_sub, ":chance_ply", 3), ## AI's Leadership bonus
                          (val_sub, ":chance_ply", ":troop_level"),
                          (store_random_in_range, ":routed", 1, 101),
                          (try_begin),
                            (le, ":routed", ":chance_ply"),
                            (agent_get_position, pos2, ":agent"),
                            (position_move_z, pos2, 200, 0),
                            (agent_clear_scripted_mode, ":agent"),
                            (agent_set_scripted_destination, ":agent", pos3, 1),
                          (try_end),
                        (end_try),
                    ]),
# [ src/scripts/ZZ_common_array_processing/simulate_retreat.py:L2-L110 ] simulate_retreat
("simulate_retreat",
    [
      (call_script, "script_music_set_situation_with_culture", mtf_sit_killed),
      (set_show_messages, 0),
      (store_script_param, ":players_side_damage", 1),
      (store_script_param, ":enemy_side_damage", 2),

      (assign, ":players_side_strength", 0),
      (assign, ":enemy_side_strength", 0),

      (assign, ":do_calculate", 1),
      (try_begin),
        (try_for_agents, ":cur_agent"),
          (agent_is_human, ":cur_agent"),
          (agent_is_alive, ":cur_agent"),
          (agent_set_slot, ":cur_agent", slot_agent_is_alive_before_retreat, 1), #needed for simulation

          (agent_get_troop_id, ":cur_troop", ":cur_agent"),
          (store_character_level, ":cur_level", ":cur_troop"),
          (val_add, ":cur_level", 5),
          (try_begin),
            (troop_is_hero, ":cur_troop"),
            (val_add, ":cur_level", 5),
          (try_end),
          (try_begin),
            (agent_is_ally, ":cur_agent"),
            (val_add, ":players_side_strength", ":cur_level"),
          (else_try),
            (val_add, ":enemy_side_strength", ":cur_level"),
          (try_end),
        (try_end),
        (eq, "$pin_player_fallen", 0),
        (lt, ":enemy_side_strength", ":players_side_strength"),
        (assign, ":do_calculate", 0),
      (try_end),

      (try_begin),
        (eq, ":do_calculate", 1),

        (assign, "$g_last_mission_player_damage", 0),
        (party_clear, "p_temp_party"),
        (party_clear, "p_temp_party_2"),
        (call_script, "script_simulate_battle_with_agents_aux", 0, ":players_side_damage"),
        (call_script, "script_simulate_battle_with_agents_aux", 1, ":enemy_side_damage"),

        (assign, ":display_casualties", 0),

        (try_begin),
          (gt, "$g_last_mission_player_damage", 0),
          (assign, ":display_casualties", 1),
          (assign, reg1, "$g_last_mission_player_damage"),
          (str_store_string, s12, "str_casualty_display_hp"),
        (else_try),
          (str_clear, s12),
        (try_end),

        (call_script, "script_print_casualties_to_s0", "p_temp_party", 1),
        (try_begin),
          (party_get_num_companion_stacks, ":num_stacks", "p_temp_party"),
          (gt, ":num_stacks", 0),
          (assign, ":display_casualties", 1),
        (try_end),
        (str_store_string_reg, s10, s0),

        (call_script, "script_print_casualties_to_s0", "p_temp_party_2", 1),
        (try_begin),
          (party_get_num_companion_stacks, ":num_stacks", "p_temp_party_2"),
          (gt, ":num_stacks", 0),
          (assign, ":display_casualties", 1),
        (try_end),
        (str_store_string_reg, s11, s0),
        (try_begin),
          (eq, ":display_casualties", 1),
          (dialog_box, "str_casualty_display", s5),
        (try_end),
      (try_end),
      (set_show_messages, 1),

      #Calculating morale penalty (can be between 0-30)
      (assign, ":ally_casualties", 0),
      (assign, ":enemy_casualties", 0),
      (assign, ":total_allies", 0),

      (try_for_agents, ":cur_agent"),
        (agent_is_human, ":cur_agent"),
        (try_begin),
          (agent_is_ally, ":cur_agent"),
          (val_add, ":total_allies", 1),
          (try_begin),
            (neg|agent_is_alive, ":cur_agent"),
            (val_add, ":ally_casualties", 1),
          (try_end),
        (else_try),
          (neg|agent_is_alive, ":cur_agent"),
          (val_add, ":enemy_casualties", 1),
        (try_end),
      (try_end),
      (store_add, ":total_casualties", ":ally_casualties", ":enemy_casualties"),
      (try_begin),
        (gt, ":total_casualties", 0),
        (store_mul, ":morale_adder", ":ally_casualties", 100),
        (val_div, ":morale_adder", ":total_casualties"),
        (val_mul, ":morale_adder", ":ally_casualties"),
        (val_div, ":morale_adder", ":total_allies"),
        (val_mul, ":morale_adder", -30),
        (val_div, ":morale_adder", 100),
        (call_script, "script_change_player_party_morale", ":morale_adder"),
      (try_end),
  ]),
